const lessons = [
  {"num": 3, "time": "00:00:59,000 --> 00:01:02,399", "arabic": "أَكَادُ لَا أُصَدِّقُ أَنَّنِي أَرَاكَ ثَانِيَةً يَا وَلَدِي", "segs": null, "full_uz": "Seni yana ko'rayotganimga deyarli ishonolmayapman, o'g'lim.", "note": null},
  {"num": 4, "time": "00:01:02,399 --> 00:01:06,719", "arabic": "وَأَنَا رَكِبْتُ جَنَاحَيْ نَعَامَةٍ لِأَطْوِيَ الْمَسَافَاتِ لِيَصِلَ إِلَيْكِ يَا أُمَّاهُ", "segs": null, "full_uz": "Men esa senga yetib borish uchun tuyaqush qanotiga minib, masofalarni qisqartirmoqchi bo'ldim, onajon.", "note": "«رَكِبَ جَنَاحَيْ نَعَامَةٍ» — «tuyaqush qanotiga minmoq», ya'ni juda tez, oshiqib yugurmoq ma'nosidagi majoziy ibora."},
  {"num": 5, "time": "00:01:06,719 --> 00:01:08,799", "arabic": "حَفِظَكَ اللَّهُ وَأَطَالَ عُمْرَكَ", "segs": null, "full_uz": "Alloh seni asrasin va umringni uzaytirsin.", "note": null},
  {"num": 6, "time": "00:01:08,799 --> 00:01:16,260", "arabic": "إِنَّ الْبَيْتَ مُوحِشٌ مِنْ دُونِكَ يَا وَلَدِي حَتَّى كُنْتُ أَشْعُرُ أَنَّ جُدْرَانَهُ سَتُطْبِقُ عَلَى رُوحِي فِي غِيَابِكَ", "segs": null, "full_uz": "Sensiz uy juda vahimali edi, o'g'lim, hatto sen yo'q paytingda devorlari jonimni siqib qo'yayozgandek his qilardim.", "note": null},
  {"num": 8, "time": "00:01:16,260 --> 00:01:19,039", "arabic": "لَا حَرَمَنِي اللَّهُ مِنْكَ يَا أَحْمَدُ", "segs": null, "full_uz": "Alloh meni sendan mahrum qilmasin, Ahmad.", "note": null},
  {"num": 9, "time": "00:01:19,039 --> 00:01:21,200", "arabic": "سَلَّمَكِ اللَّهُ يَا أُمَّاهُ", "segs": null, "full_uz": "Alloh seni asrasin, onajon.", "note": null},
  {"num": 10, "time": "00:01:21,200 --> 00:01:24,700", "arabic": "وَأَنَا وَاللَّهِ لَمْ يُفَارِقْنِي طَيْفُكَ لَحْظَةً مِنْ لَيْلٍ أَوْ نَهَارٍ", "segs": null, "full_uz": "Men esa, vallohi, bir lahza ham, kechayu kunduz sening xayoling meni tark etmadi.", "note": null},
  {"num": 11, "time": "00:01:24,700 --> 00:01:26,980", "arabic": "كُنْتَ حَاضِرًا مَعِي فِي كُلِّ خُطْوَةٍ", "segs": null, "full_uz": "Sen har bir qadamimda men bilan bo'lding.", "note": null},
  {"num": 12, "time": "00:01:26,980 --> 00:01:29,219", "arabic": "هَاتِ أَخْبِرْنِي مَا عِنْدَكَ يَا أَحْمَدُ", "segs": null, "full_uz": "Qani, senda nima bor, aytib ber, Ahmad.", "note": null},
  {"num": 13, "time": "00:01:29,219 --> 00:01:32,780", "arabic": "مُنْذُ خُرُوجِكَ مِنْ بَغْدَادَ حَتَّى عَوْدَتِكَ إِلَى أُمِّكَ", "segs": null, "full_uz": "Bag'doddan chiqqaningdan to onangga qaytishingcha.", "note": null},
  {"num": 14, "time": "00:01:48,719 --> 00:01:50,300", "arabic": "سَيِّدَ بَدْرٍ، يَا سَيِّدَ بَدْرٍ", "segs": null, "full_uz": "Sayyid Badr, ey Sayyid Badr.", "note": null},
  {"num": 16, "time": "00:01:50,300 --> 00:01:52,280", "arabic": "اَلسَّلَامُ عَلَيْكُمْ يَا أَخِي", "segs": null, "full_uz": "Sizga salom, birodarim.", "note": null},
  {"num": 17, "time": "00:01:52,280 --> 00:01:54,280", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 18, "time": "00:01:54,280 --> 00:01:58,180", "arabic": "أَنَا أَخُوكَ فِي اللَّهِ أُسَامَةُ الْبَكْرِيُّ", "segs": null, "full_uz": "Men Alloh yo'lidagi birodaringiz Usoma al-Bakriyman.", "note": null},
  {"num": 19, "time": "00:01:58,180 --> 00:02:06,439", "arabic": "لَعَلَّ أَبَاكِ بَحَثَ عَنْكِ كَثِيرًا أَيْضًا وَلَمَّا يَجِدْكِ", "segs": null, "full_uz": "Balki otang ham seni ko'p qidirgandir, lekin hali topolmagandir.", "note": null},
  {"num": 20, "time": "00:02:06,439 --> 00:02:08,580", "arabic": "وَأَنَا أَيْضًا يَا مَرْوَانُ", "segs": null, "full_uz": "Men ham, Marvon.", "note": null},
  {"num": 21, "time": "00:02:08,580 --> 00:02:14,420", "arabic": "أَمْضَيْتُ أَيَّامًا أَبْحَثُ عَنْهُ مَعَ خَالِدٍ جَزَاهُ اللَّهُ خَيْرًا وَلَمْ نَقَعْ لَهُ عَلَى أَثَرٍ", "segs": null, "full_uz": "Xolid bilan birga — Alloh unga yaxshilik bersin — bir necha kun uni qidirdim, lekin izini topolmadik.", "note": null},
  {"num": 23, "time": "00:02:14,420 --> 00:02:17,920", "arabic": "يَفْعَلُ اللَّهُ مَا يَشَاءُ يَا شَهْنَازُ", "segs": null, "full_uz": "Alloh xohlagan narsasini qiladi, Shahnoz.", "note": null},
  {"num": 25, "time": "00:02:17,920 --> 00:02:22,740", "arabic": "مَا زِلْتُ أَذْكُرُ آخِرَ اللِّقَاءِ بَيْنَنَا وَكَأَنَّهُ السَّاعَةَ", "segs": null, "full_uz": "Oramizdagi so'nggi uchrashuvni hozirgidek eslayman.", "note": null},
  {"num": 26, "time": "00:02:22,740 --> 00:02:28,420", "arabic": "كَانَ عِنْدَ دُكَّانِ التَّاجِرِ وَبَعْدَهَا افْتَرَقْنَا كَيْفَ لَا أَدْرِي", "segs": null, "full_uz": "Savdogar do'koni yonida edi, va shundan keyin ajraldik — qanday bo'lganini bilmayman.", "note": null},
  {"num": 29, "time": "00:02:28,420 --> 00:02:32,719", "arabic": "هَلْ قُلْتَ عِنْدَ دُكَّانِ التَّاجِرِ؟", "segs": null, "full_uz": "Savdogar do'koni yonida dedingizmi?", "note": null},
  {"num": 30, "time": "00:02:32,719 --> 00:02:33,080", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 31, "time": "00:02:33,080 --> 00:02:39,520", "arabic": "تَاجِرٌ فِي بَغْدَادَ، كَانَ أَبِي يَبِيعُ لَهُ أَمْشَاطَ الْفِضَّةِ", "segs": null, "full_uz": "Bag'doddagi savdogar — otam unga kumush taroqlar sotardi.", "note": null},
  {"num": 33, "time": "00:02:48,939 --> 00:02:50,900", "arabic": "لَمْ أَجِدْ مَلْجَأً غَيْرَكَ يَا أَخِي", "segs": null, "full_uz": "Sendan boshqa boradigan joyim yo'q, birodarim.", "note": null},
  {"num": 34, "time": "00:02:50,900 --> 00:02:53,020", "arabic": "فَأَنْتَ وَحْدَكَ مَنْ يَسْتَطِيعُ مُسَاعَدَتِي", "segs": null, "full_uz": "Faqat sengina menga yordam bera olasan.", "note": null},
  {"num": 35, "time": "00:02:53,020 --> 00:02:54,860", "arabic": "وَمَنْ قَالَ لَكَ إِنَّنِي", "segs": null, "full_uz": "Kim senga aytdi, men...", "note": null},
  {"num": 36, "time": "00:02:54,860 --> 00:02:57,800", "arabic": "رَأَيْتُكَ مَرَّةً مَعَ الشَّيْخِ الْمَرِيسِيِّ أَوْ تَعْرِفُ الشَّيْخَ؟", "segs": null, "full_uz": "Sizni bir marta shayx Marisiy bilan ko'rgandim — shayxni tanirsizmi?", "note": null},
  {"num": 38, "time": "00:02:57,800 --> 00:03:01,280", "arabic": "لَيْتَ لِي أَنْ أَزْعُمَ هَذَا وَلَكِنَّهُ كَالنَّجْمِ يُرَى وَلَا يُطَالُ", "segs": null, "full_uz": "Koshki shunday deya olsam edi, lekin u — yulduz kabi, ko'rinadi-yu, unga yetib bo'lmaydi.", "note": "«كَالنَّجْمِ يُرَى وَلَا يُطَالُ» — «yulduz kabi ko'rinadi-yu, yetib bo'lmaydi», ya'ni yaqinlashib bo'lmaydigan, olis odam ma'nosidagi majoziy ibora."},
  {"num": 39, "time": "00:03:01,280 --> 00:03:07,020", "arabic": "بِمَ أَسْتَطِيعُ أَنْ أَخْدِمَكَ يَا أُسَامَةُ؟", "segs": null, "full_uz": "Sizga qanday xizmat qila olaman, Usoma?", "note": null},
  {"num": 40, "time": "00:03:07,020 --> 00:03:09,500", "arabic": "أُرِيدُكَ أَنْ تُقَدِّمَنِي إِلَى الشَّيْخِ الْمَرِيسِيِّ لَا غَيْرَ", "segs": null, "full_uz": "Sizdan meni shayx Marisiyga tanishtirishingizni istayman, boshqa hech narsa emas.", "note": null},
  {"num": 41, "time": "00:03:09,500 --> 00:03:13,020", "arabic": "وَلِمَاذَا لَا تُقَدِّمُ لَهُ نَفْسَكَ بِنَفْسِكَ؟", "segs": null, "full_uz": "Nega o'zingizni o'zingiz unga tanishtirmaysiz?", "note": null},
  {"num": 42, "time": "00:03:13,620 --> 00:03:17,659", "arabic": "اَلشَّيْخُ أَبُو عَبْدِ الرَّحْمَنِ مُتَوَاضِعٌ وَيَسْتَقْبِلُ أَيَّ قَاصِدٍ اذْهَبْ إِلَيْهِ", "segs": null, "full_uz": "Shayx Abu Abdurahmon kamtar, va har qanday tashrif buyuruvchini qabul qiladi — boring undan.", "note": null},
  {"num": 43, "time": "00:03:17,659 --> 00:03:23,960", "arabic": "أُرِيدُ أَنْ أَتَعَرَّفَ إِلَيْهِ مِنْ خِلَالِ مَنْ يَعْرِفُهُ وَيَثِقُ بِهِ الشَّيْخُ حَتَّى يَضُمَّنِي فِي عِدَادِ مُرِيدِيهِ", "segs": null, "full_uz": "Shayx uni bilib, ishonadigan kishi orqali tanishishni istayman, toki u meni izdoshlari qatoriga qo'shsin.", "note": null},
  {"num": 45, "time": "00:03:23,960 --> 00:03:31,620", "arabic": "أَتَعْرِفُ أَنَّ رُفْقَةَ الشَّيْخِ مُخَاطَرَةٌ كَبِيرَةٌ؟", "segs": null, "full_uz": "Bilasizmi, shayx bilan hamrohlik katta xavf-tavakkalligini?", "note": null},
  {"num": 46, "time": "00:03:31,620 --> 00:03:36,780", "arabic": "أَعْرِفُ أَعْرِفُ، وَأَعْرِفُ أَنَّ زَبَانِيَتَهُ يَتَحَرَّوْنَ يَتَلَصَّصُونَ عَلَى الْكَبِيرِ وَالصَّغِيرِ", "segs": null, "full_uz": "Bilaman, bilaman, va uning jallodlari katta-kichikni ta'qib qilib, poylab yurishini ham bilaman.", "note": null},
  {"num": 48, "time": "00:03:36,780 --> 00:03:41,079", "arabic": "وَأَنَّهُمْ لَمْ يَعْثُرُوا عَلَى دَلِيلٍ وَاحِدٍ يُدِينُ الشَّيْخَ حَتَّى لَحْظَةِ حَدِيثِنَا هَذَا", "segs": null, "full_uz": "Va shu suhbatimizgacha ular shayxni ayblovchi bironta ham dalil topolmaganini ham bilaman.", "note": null},
  {"num": 49, "time": "00:03:41,079 --> 00:03:47,199", "arabic": "وَأَعْرِفُ أَيْضًا أَنَّ حَيَاتِي لَيْسَتْ أَكْثَرَ قِيمَةً مِنْ حَيَاةِ شَيْخِنَا حَفِظَهُ اللَّهُ", "segs": null, "full_uz": "Va yana bilamanki, mening hayotim shayximiz hayotidan — Alloh uni asrasin — qadrliroq emas.", "note": null},
  {"num": 50, "time": "00:03:47,199 --> 00:03:52,199", "arabic": "لَا أَدْرِي يَا أُسَامَةُ لَا أَدْرِي", "segs": null, "full_uz": "Bilmayman, Usoma, bilmayman.", "note": null},
  {"num": 51, "time": "00:03:52,199 --> 00:03:56,619", "arabic": "أَرْجُوكَ أَرْجُوكَ أَنْ لَا تَرُدَّنِي خَائِبًا يَا بَدْرُ", "segs": null, "full_uz": "Iltimos, iltimos, meni ko'ngli sindirilgan holda qaytarma, Badr.", "note": null},
  {"num": 52, "time": "00:03:56,619 --> 00:04:02,699", "arabic": "حَسَنًا سَأُكَلِّمُ الشَّيْخَ فِي أَمْرِكَ أَوَّلًا وَعِنْدَهَا سَيَرَى مَا يَكُونُ", "segs": null, "full_uz": "Xo'p, avval shayx bilan sizning ishingiz haqida gaplashaman, keyin nima bo'lishini o'zi ko'radi.", "note": null},
  {"num": 53, "time": "00:04:02,699 --> 00:04:06,019", "arabic": "شُكْرًا لَكَ يَا سَيِّدَ بَدْرٍ شُكْرًا لَكَ", "segs": null, "full_uz": "Rahmat sizga, Sayyid Badr, rahmat sizga.", "note": null},
  {"num": 54, "time": "00:04:06,019 --> 00:04:08,799", "arabic": "لَا بَأْسَ وَلَكِنْ أَيْنَ سَأَجِدُكَ", "segs": null, "full_uz": "Mayli, lekin sizni qayerdan topaman?", "note": null},
  {"num": 55, "time": "00:04:08,799 --> 00:04:12,060", "arabic": "فَلْنَلْتَقِ عِنْدَ النَّهْرِ عِنْدَ طَرَفِ الْجِسْرِ", "segs": null, "full_uz": "Daryo bo'yida, ko'prik chetida uchrashaylik.", "note": null},
  {"num": 56, "time": "00:04:12,060 --> 00:04:15,060", "arabic": "حَسَنًا هَذَا مُنَاسِبٌ إِلَى اللِّقَاءِ يَا أُسَامَةُ", "segs": null, "full_uz": "Xo'p, bu qulay. Ko'rishguncha, Usoma.", "note": null},
  {"num": 57, "time": "00:04:15,579 --> 00:04:16,500", "arabic": "إِلَى اللِّقَاءِ", "segs": null, "full_uz": "Ko'rishguncha.", "note": null},
  {"num": 58, "time": "00:04:16,500 --> 00:04:42,500", "arabic": "مَا لِي أَرَى مَوْلَايَ الرَّشِيدَ عَلَى غَيْرِ سَجِيَّتِهِ الَّتِي أَعْرِفُهُ بِهَا؟", "segs": null, "full_uz": "Nega xo'jayinim ar-Rashidni bilgan tabiatidan boshqacha holda ko'rayapman?", "note": null},
  {"num": 59, "time": "00:04:44,500 --> 00:04:47,579", "arabic": "مَا بِكَ يَا مَوْلَايَ؟ لِمَاذَا كُلُّ هَذَا الشُّرُودِ وَالْحُزْنِ", "segs": null, "full_uz": "Sizga nima bo'ldi, xo'jayinim? Bu qadar xayolparastlik va g'am nimadan?", "note": null},
  {"num": 61, "time": "00:04:47,579 --> 00:04:54,660", "arabic": "لَا شَيْءَ يَا زُبَيْدَةُ لَا شَيْءَ", "segs": null, "full_uz": "Hech narsa, Zubayda, hech narsa.", "note": null},
  {"num": 63, "time": "00:04:54,660 --> 00:05:04,540", "arabic": "لَوْ قُلْتَ هَذَا الْكَلَامَ لِغَيْرِي لَصَدَّقَكَ", "segs": null, "full_uz": "Bu gapni menga emas, boshqasiga aytganingda, ishonardi.", "note": null},
  {"num": 64, "time": "00:05:04,540 --> 00:05:08,339", "arabic": "أَمَّا أَنَا، أَنَا الَّتِي تَعْرِفُكَ جَيِّدًا", "segs": null, "full_uz": "Men esa — men seni yaxshi biladigan ayolman.", "note": null},
  {"num": 66, "time": "00:05:08,339 --> 00:05:14,019", "arabic": "أَنَا الَّتِي تَشْعُرُ بِكُلِّ أَنْفَاسِكَ وَهُمُومِكَ فَلَا يَخْفَى عَلَيَّ", "segs": null, "full_uz": "Men — nafasing va tashvishlaringni his qiladigan ayolman, shuning uchun mendan yashirin qolmaydi.", "note": null},
  {"num": 68, "time": "00:05:14,019 --> 00:05:21,219", "arabic": "لَا أُخْفِيكِ يَا زُبَيْدَةُ", "segs": null, "full_uz": "Sendan yashirmayman, Zubayda.", "note": null},
  {"num": 69, "time": "00:05:21,219 --> 00:05:25,819", "arabic": "وَاللَّهِ إِنْ حَدَثَ لِجَعْفَرٍ مَا حَدَثَ", "segs": null, "full_uz": "Vallohi, Ja'farga bo'lgan voqea sodir bo'lgani...", "note": null},
  {"num": 70, "time": "00:05:25,819 --> 00:05:30,259", "arabic": "وَأَنَا نَادِمٌ أَجِدُ صَدْرِي لَا يَرَاحُ", "segs": null, "full_uz": "Men esa pushaymon bo'lib, ko'nglim tinchimayapti.", "note": null},
  {"num": 71, "time": "00:05:30,259 --> 00:05:32,740", "arabic": "فُتَّتْ نَفْسِي يَا مَوْلَايَ", "segs": null, "full_uz": "Ichim parchalanib ketdi, xo'jayinim.", "note": null},
  {"num": 72, "time": "00:05:44,019 --> 00:05:57,379", "arabic": "لَيْتَ صَاحِبِي كَانَ يَعْلَمُ مِقْدَارَ مَحَبَّتِي لَهُ", "segs": null, "full_uz": "Koshki do'stim unga bo'lgan muhabbatimning miqdorini bilsa edi.", "note": null},
  {"num": 73, "time": "00:05:57,379 --> 00:06:01,479", "arabic": "لَكَانَ جَنَّبَنِي فِعْلَ ذَلِكَ", "segs": null, "full_uz": "Meni bu ishni qilishdan asrardi.", "note": null},
  {"num": 74, "time": "00:06:01,479 --> 00:06:08,439", "arabic": "غَفَرَ اللَّهُ لَهُ وَثَبَّتَكَ عَلَى الْحَقِّ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh uni kechirsin, va sizni haq yo'lda mustahkam qilsin, mo'minlar amiri.", "note": null},
  {"num": 76, "time": "00:06:08,439 --> 00:06:11,539", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 77, "time": "00:06:14,019 --> 00:06:19,060", "arabic": "أَسْأَلُ اللَّهَ أَنْ يَغْفِرَ لَهُ، لَا أَسْتَطِيعُ أَنْ أَكُونَ أَكْثَرَ مِنْ ذَلِكَ", "segs": null, "full_uz": "Allohdan uni kechirishini so'rayman, bundan ortig'ini qila olmayman.", "note": null},
  {"num": 79, "time": "00:06:19,060 --> 00:06:33,639", "arabic": "أُرِيدُ أَنْ أُفَاتِحَكِ بِأَمْرٍ يَا أُخْتَاهُ", "segs": null, "full_uz": "Senga bir masalani ochiq aytmoqchiman, singlim.", "note": null},
  {"num": 80, "time": "00:06:33,639 --> 00:06:36,879", "arabic": "قُلْ يَا أَخِي إِنِّي أَسْمَعُكَ", "segs": null, "full_uz": "Ayt, akajon, seni tinglayapman.", "note": null},
  {"num": 82, "time": "00:06:36,879 --> 00:06:48,900", "arabic": "لَقَدْ كَثُرَتْ عَلَيَّ مَشَاغِلِي وَلَمْ يَعُدْ لَدَيَّ وَقْتٌ يُعِينُنِي عَلَى الِاعْتِنَاءِ بِكِ، وَقَدْ أَصْبَحَ مِنَ الضَّرُورِيِّ أَنْ آتِيَ لَكِ بِجَارِيَةٍ تَهْتَمُّ بِكِ وَتَعْتَنِي بِشُؤُونِكِ فِي غِيَابِي", "segs": [{"ar": "لَقَدْ كَثُرَتْ عَلَيَّ مَشَاغِلِي وَلَمْ يَعُدْ لَدَيَّ وَقْتٌ يُعِينُنِي عَلَى الِاعْتِنَاءِ بِكِ", "uz": "ishlarim ko'payib ketdi, va senga g'amxo'rlik qilishga yordam beradigan vaqtim qolmadi"}, {"ar": "وَقَدْ أَصْبَحَ مِنَ الضَّرُورِيِّ أَنْ آتِيَ لَكِ بِجَارِيَةٍ تَهْتَمُّ بِكِ وَتَعْتَنِي بِشُؤُونِكِ فِي غِيَابِي", "uz": "va endi senga g'amxo'rlik qiladigan, yo'qligimda ishlaringga qaraydigan bir cho'ri olib kelishim zarur bo'lib qoldi"}], "full_uz": "Ishlarim ko'payib ketdi, va senga g'amxo'rlik qilishga yordam beradigan vaqtim qolmadi, endi senga g'amxo'rlik qiladigan, yo'qligimda ishlaringga qaraydigan bir cho'ri olib kelishim zarur bo'lib qoldi.", "note": null},
  {"num": 83, "time": "00:06:54,560 --> 00:06:56,020", "arabic": "أَعَانَكِ اللَّهُ يَا أَخِي", "segs": null, "full_uz": "Alloh senga yordam bersin, akajon.", "note": null},
  {"num": 84, "time": "00:06:56,020 --> 00:07:02,480", "arabic": "لَا تَخَفْ عَلَيَّ، فَابْنَةُ عَمِّكَ لَا تُقَصِّرُ فِي حَقِّي وَهِيَ تَرْعَانِي وَتَهْتَمُّ بِي كُلَّ الْوَقْتِ", "segs": null, "full_uz": "Men uchun xavotir olma — amaking qizi menga bo'lgan burchida kamlik qilmayapti, u doim menga g'amxo'rlik qiladi.", "note": null},
  {"num": 90, "time": "00:07:04,000 --> 00:07:07,259", "arabic": "بَارَكَ اللَّهُ فِيهَا", "segs": null, "full_uz": "Alloh unga baraka bersin.", "note": null},
  {"num": 91, "time": "00:07:07,259 --> 00:07:12,640", "arabic": "وَأَنَا أُقَدِّرُ لَهَا ذَلِكَ وَلَكِنِّي لَا أُرِيدُ أَنْ أُثَقِّلَ عَلَى أَحَدٍ", "segs": null, "full_uz": "Men buni qadrlayman, lekin hech kimga og'irlik solishni istamayman.", "note": null},
  {"num": 93, "time": "00:07:12,639 --> 00:07:19,560", "arabic": "حَسَنًا كَمَا تَشَائِينَ، وَلَكِنَّكِ إِلَى الْآنَ لَمْ تَجِدِي الْجَارِيَةَ الْمُنَاسِبَةَ", "segs": null, "full_uz": "Xo'p, qanday xohlasang, lekin hozirgacha munosib cho'rini topmading.", "note": null},
  {"num": 95, "time": "00:07:19,560 --> 00:07:22,159", "arabic": "فَمَاذَا نَفْعَلُ؟ أَجَلْ", "segs": null, "full_uz": "Unda nima qilamiz? — Ha.", "note": null},
  {"num": 97, "time": "00:07:22,159 --> 00:07:30,139", "arabic": "لَمْ أَجِدْ جَارِيَةً يَطْمَئِنُّ لَهَا قَلْبِي إِلَّا تِلْكَ الْفَتَاةَ الْمِسْكِينَةَ الَّتِي حَدَّثْتُكَ عَنْهَا مِنْ قَبْلُ", "segs": null, "full_uz": "Qalbim faqat sizga ilgari aytgan bechora qizga tinchlangan, boshqa hech qanday cho'riga tinchlanmadi.", "note": null},
  {"num": 99, "time": "00:07:30,139 --> 00:07:35,659", "arabic": "كَمَا تُرِيدُ، إِنْ كُنْتَ تَرَاهَا مُنَاسِبَةً فَلَا بَأْسَ", "segs": null, "full_uz": "Xohlaganingdek, agar munosib deb bilsang, mayli.", "note": null},
  {"num": 101, "time": "00:07:35,659 --> 00:07:38,319", "arabic": "أَنَا مُوَافِقَةٌ", "segs": null, "full_uz": "Men roziman.", "note": null},
  {"num": 102, "time": "00:07:42,639 --> 00:07:54,839", "arabic": "صَدِّقِينِي يَا أُخْتَاهُ", "segs": null, "full_uz": "Ishon menga, singlim.", "note": null},
  {"num": 103, "time": "00:07:54,839 --> 00:08:00,139", "arabic": "لَوْ لَمْ أَكُنْ مُتَأَكِّدًا مِنْ أَنَّهَا مُنَاسِبَةٌ مَا كُنْتُ مُصِرًّا عَلَيْهَا", "segs": null, "full_uz": "Agar munosibligiga aminlik hosil qilmaganimda, unga qat'iy turmagan bo'lardim.", "note": null},
  {"num": 105, "time": "00:08:00,139 --> 00:08:06,139", "arabic": "وَأَنَا أَثِقُ بِاخْتِيَارِكَ وَأَعْرِفُ أَنَّكَ لَا تَفْعَلُ إِلَّا خَيْرًا وَصَوَابًا", "segs": null, "full_uz": "Men tanlovingga ishonaman, va faqat yaxshilik va to'g'ri ish qilishingni bilaman.", "note": null},
  {"num": 107, "time": "00:08:08,219 --> 00:08:09,699", "arabic": "أَحْضِرْهَا مَتَى شِئْتَ", "segs": null, "full_uz": "Xohlagan vaqtingda olib kel.", "note": null},
  {"num": 108, "time": "00:08:12,639 --> 00:08:28,300", "arabic": "هَلْ تَأَكَّدْتُمْ مِنْ صِحَّةِ الْأَخْبَارِ الْوَارِدَةِ مِنَ الْقُسْطَنْطِينِيَّةِ يَا ابْنَ الرَّبِيعِ؟", "segs": null, "full_uz": "Qustantiniyadan kelgan xabarlarning to'g'riligiga ishonch hosil qildingizmi, Ibn ar-Rabi'?", "note": null},
  {"num": 109, "time": "00:08:28,300 --> 00:08:31,379", "arabic": "أَجَلْ يَا أَمِيرَ الْمُؤْمِنِينَ، اَلْأَخْبَارُ صَحِيحَةٌ", "segs": null, "full_uz": "Ha, mo'minlar amiri, xabarlar to'g'ri.", "note": null},
  {"num": 111, "time": "00:08:31,379 --> 00:08:39,939", "arabic": "يَبْدُو أَنَّ الرُّومَ قَدْ خَلَعُوا مَلِكَتَهُمْ أُغُسْطَةَ، وَثَمَّةَ فَوْضَى فِي صُفُوفِ الرُّومِ تَكَادُ تُذْهِبُ عَرْشَهُمْ وَمُلْكَهُمْ", "segs": null, "full_uz": "Rumliklar malikasi Ag'ustani taxtdan tushirganga o'xshaydi, va Rum safida taxtu-mulklarini deyarli yo'qotib qo'yayozgan tartibsizlik hukm surmoqda.", "note": null},
  {"num": 113, "time": "00:08:39,940 --> 00:08:46,380", "arabic": "وَهَلْ جُنْدُنَا فِي الثُّغُورِ عَلَى أُهْبَةِ الِاسْتِعْدَادِ؟", "segs": null, "full_uz": "Chegaralardagi qo'shinimiz tayyorgarlik holatidami?", "note": null},
  {"num": 114, "time": "00:08:46,380 --> 00:08:52,260", "arabic": "أَجَلْ يَا مَوْلَايَ وَقَدْ تَوَلَّى الْإِشْرَافَ عَلَى ذَلِكَ الْأَمِيرُ الْقَاسِمُ بْنُ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Ha, xo'jayinim, unga nazoratni amir Qosim ibn Amirul-Mo'minin o'z zimmasiga olgan.", "note": null},
  {"num": 115, "time": "00:08:52,260 --> 00:09:00,100", "arabic": "مَا لِهَؤُلَاءِ الْحَمْقَى قَدْ ثَارُوا عَلَى مَلِكَتِهِمْ؟ وَاللَّهِ لَقَدْ كَانَتْ تَسُوسُهُمْ بِعَقْلٍ وَحِكْمَةٍ", "segs": null, "full_uz": "Bu ahmoqlarga nima bo'lgan, malikalariga qarshi qo'zg'olon ko'targanlar? Vallohi, u ularni aql va hikmat bilan boshqarardi.", "note": null},
  {"num": 117, "time": "00:09:00,100 --> 00:09:05,620", "arabic": "هَؤُلَاءِ الْعَجَمُ يَا مَوْلَايَ يَسْتَبْدِلُونَ مُلُوكَهُمْ كَمَا يَسْتَبْدِلُونَ مَلَابِسَهُمْ", "segs": null, "full_uz": "Bu ajamiylar, xo'jayinim, kiyimlarini almashtirgandek podshohlarini ham almashtirib turishadi.", "note": null},
  {"num": 118, "time": "00:09:05,620 --> 00:09:10,419", "arabic": "فَمَا إِنْ يَطْمَعَ أَحَدُهُمْ فِي الْمُلْكِ، وَمَا أَكْثَرَ الطَّامِعِينَ يَا مَوْلَايَ", "segs": null, "full_uz": "Ulardan biri taxtga ko'z olaytirsa bo'ldi — va ko'z olaytiradiganlar qanchalik ko'p, xo'jayinim.", "note": null},
  {"num": 120, "time": "00:09:10,419 --> 00:09:17,500", "arabic": "حَتَّى يَنْقَضُّوا عَلَى مَلِكِهِمْ وَيَقْتُلُوهُ وَلَوْ كَانَ مَلِكًا، وَيَسْتَوْلُوا عَرْشَهُ وَمُلْكَهُ", "segs": null, "full_uz": "Podshohlariga hujum qilib, hatto u [munosib] shoh bo'lsa ham, uni o'ldirib, taxti va mulkini egallab olishadi.", "note": null},
  {"num": 124, "time": "00:09:17,500 --> 00:09:23,740", "arabic": "تَعْسًا لَهُمْ، أَلَا يَعْقِلُونَ، أَلَا يَعْلَمُونَ أَنَّ مَنْ خَلَعَ يُخْلَعُ وَلَوْ بَعْدَ حِينٍ", "segs": null, "full_uz": "Yo'q bo'lishlarini, aqllari yo'qmi, birovni taxtdan ag'dargan o'zi ham ertami-kechmi ag'darilishini bilishmaydimi?", "note": null},
  {"num": 128, "time": "00:09:23,740 --> 00:09:30,240", "arabic": "أَلَا يَعْلَمُونَ أَنَّ الْمُلْكَ لَا يَدُومُ إِلَّا لِصَاحِبِ الْمُلْكِ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Bilishmaydimi, mulk faqat mulk egasi — Alloh subhanahu va taologa mangu qolishini?", "note": null},
  {"num": 130, "time": "00:09:30,240 --> 00:09:35,340", "arabic": "أَمْ أَنَّ الطَّمَعَ وَشَهْوَةَ الْحُكْمِ أَنْسَتْهُمُ الِاكْتِرَاثَ لِحَيَاةِ النَّاسِ", "segs": null, "full_uz": "Yoki ochko'zlik va hokimiyat ishtiyoqi ularga odamlar hayotiga befarq bo'lishni unutdirdimi.", "note": null},
  {"num": 132, "time": "00:09:35,340 --> 00:09:44,300", "arabic": "رُبَّمَا اسْتَغَلَّ بَعْضُ أُمَرَائِهِمْ حَالَةَ الْفَوْضَى الدَّائِرَةِ بَيْنَهُمْ لِيَنْقُضُوا الْعُهُودَ وَالْمَوَاثِيقَ", "segs": null, "full_uz": "Balki ba'zi hukmdorlari orasidagi tartibsizlik holatidan foydalanib, ahd-paymonlarni buzishgandir.", "note": null},
  {"num": 134, "time": "00:09:44,300 --> 00:09:52,280", "arabic": "أَوْ رُبَّمَا اسْتَغَلُّوا ذَلِكَ لِصَرْفِ أَنْظَارِ رَعَايَاهُمْ فَنَقَلُوا الْمَعْرَكَةَ إِلَى الثُّغُورِ", "segs": null, "full_uz": "Yoki balki bundan xalqlarining nazarini chalg'itish uchun foydalanib, jangni chegaralarga ko'chirishgandir.", "note": null},
  {"num": 136, "time": "00:09:52,280 --> 00:09:58,920", "arabic": "اَلرُّومُ أَجْبَنُ مِنْ ذَلِكَ يَا ابْنَ الرَّبِيعِ، أَجْبَنُ مِنْ ذَلِكَ", "segs": null, "full_uz": "Rumliklar bundan ham qo'rqoqroq, Ibn ar-Rabi', bundan ham qo'rqoqroq.", "note": null},
  {"num": 138, "time": "00:10:05,340 --> 00:10:13,920", "arabic": "اِسْمَعْ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Eshit, Abu Abdulloh.", "note": null},
  {"num": 139, "time": "00:10:13,920 --> 00:10:19,560", "arabic": "لَقَدْ عَزَمْتُ الْخُرُوجَ حَجًّا إِلَى مَكَّةَ شَرَّفَهَا اللَّهُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, Makkaga — Alloh uni sharaflagan bo'lsin — hajga borishga qat'iy qaror qildim.", "note": null},
  {"num": 140, "time": "00:10:19,560 --> 00:10:26,860", "arabic": "تَذَكَّرْ أَنَّكَ وَعَدْتَنِي أَنْ نَخْرُجَ سَوِيًّا نَحُجَّ بَيْتَ اللَّهِ", "segs": null, "full_uz": "Yodingdami, sen menga birga chiqib, Allohning uyini haj qilamiz deb va'da bergan eding.", "note": null},
  {"num": 142, "time": "00:10:26,860 --> 00:10:30,340", "arabic": "وَنَنْقَطِعَ إِلَى الْإِمَامِ سُفْيَانَ بْنِ عُيَيْنَةَ", "segs": null, "full_uz": "Va imom Sufyon ibn Uyaynaga bag'ishlanamiz.", "note": null},
  {"num": 143, "time": "00:10:30,340 --> 00:10:31,340", "arabic": "مَا رَأْيُكَ؟", "segs": null, "full_uz": "Fikringiz qanday?", "note": null},
  {"num": 144, "time": "00:10:32,180 --> 00:10:36,460", "arabic": "كُلُّ شَيْءٍ بِقَدَرٍ يَا ابْنَ مَعِينٍ وَإِلَى أَنْ يَأْتِيَ مَوْعِدُهُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Har narsa taqdirga bog'liq, Ibn Ma'in, va uning vaqti kelguncha, Alloh xohlasa.", "note": null},
  {"num": 146, "time": "00:10:36,460 --> 00:10:38,879", "arabic": "نُفَوِّضُ اللَّهَ فِيمَا لَا نَعْلَمُهُ", "segs": null, "full_uz": "Bilmagan narsamizni Allohga topshiramiz.", "note": null},
  {"num": 147, "time": "00:10:38,879 --> 00:11:01,940", "arabic": "يَبْدُو أَنَّ نَقْفُورَ هَذَا قَدِ اسْتَأْثَرَ بِالْحُكْمِ دُونَ بَاقِي أُمَرَاءِ الرُّومِ", "segs": null, "full_uz": "Bu Naqfur boshqa Rum amirlaridan ayri hokimiyatni faqat o'ziga olib qo'yganga o'xshaydi.", "note": "اِسْتَأْثَرَ بِـ — biror narsani boshqalardan mahrum qilib, yolg'iz o'ziga olib qo'yish, monopoliya qilish ma'nosini beradi."},
  {"num": 148, "time": "00:11:01,940 --> 00:11:05,780", "arabic": "سَمِعْتُ مِنْ رُومِيٍّ مُسْلِمٍ مِنْ سُكَّانِ بَغْدَادَ حَمَاهَا اللَّهُ", "segs": null, "full_uz": "Bag'dod aholisidan bo'lgan — Alloh uni asrasin — musulmon bir rumlikdan eshitdim.", "note": null},
  {"num": 149, "time": "00:11:05,780 --> 00:11:11,020", "arabic": "أَنَّ نَقْفُورَ هَذَا مِنْ أَوْلَادِ جَفْنَةَ مِنْ غَسَّانَ قَحْطَانِيِّ الْأُرُومَةِ", "segs": null, "full_uz": "Bu Naqfur Jafna avlodidan, G'assondan, qahtoniy asl-nasabdan ekan.", "note": null},
  {"num": 150, "time": "00:11:11,020 --> 00:11:17,660", "arabic": "أَيُعْقَلُ أَنْ يَرْضَى بَنُو الْأَصْفَرِ مِنَ الرُّومِ أَنْ يُوَلُّوا عَلَيْهِمْ مَلِكًا مِنْ أَصْلٍ عَرَبِيٍّ؟", "segs": null, "full_uz": "Rumlardan bo'lgan Banu al-Asfar arab asl-nasabidan bo'lgan bir podshohni o'zlariga hukmdor qilib tayinlashga rozi bo'lishlari mumkinmi?", "note": "بَنُو الْأَصْفَر — qadimgi arab tilida Vizantiya (Rum) imperiyasi va uning xalqiga nisbatan ishlatilgan ta'bir."},
  {"num": 151, "time": "00:11:17,660 --> 00:11:20,320", "arabic": "يُقَالُ إِنَّهُ دَاهِيَةٌ لَا يُشَقُّ لَهُ غُبَارٌ", "segs": null, "full_uz": "Aytishlaricha, u tengsiz ayyor kishi ekan.", "note": "لَا يُشَقُّ لَهُ غُبَار — so'zma-so'z «changiga yetib bo'lmaydi», ma'nosi — tengi yo'q, hech kim unga yetolmaydi."},
  {"num": 152, "time": "00:11:20,320 --> 00:11:38,800", "arabic": "يَا ابْنَ الرَّبِيعِ، غَدًا صَبَاحًا جَهِّزْ لِي مَوْكِبِي، أُرِيدُ أَنْ أَذْهَبَ لِتَفَقُّدِ الثُّغُورِ", "segs": [{"ar": "يَا ابْنَ الرَّبِيعِ، غَدًا صَبَاحًا جَهِّزْ لِي مَوْكِبِي", "uz": "Ey Ibn ar-Rabi', ertaga ertalab karvonimni tayyorla"}, {"ar": "أُرِيدُ أَنْ أَذْهَبَ لِتَفَقُّدِ الثُّغُورِ", "uz": "chegara qo'riqxonalarini ko'zdan kechirgani bormoqchiman"}], "full_uz": "Ey Ibn ar-Rabi', ertaga ertalab karvonimni tayyorla — chegara qo'riqxonalarini ko'zdan kechirgani bormoqchiman.", "note": null},
  {"num": 156, "time": "00:11:50,320 --> 00:12:05,600", "arabic": "لَمْ تَقُلْ لِي اسْمَ الْفَتَاةِ؟", "segs": null, "full_uz": "Menga qizning ismini aytmading-ku?", "note": null},
  {"num": 157, "time": "00:12:05,600 --> 00:12:10,500", "arabic": "رَغَدُ، اسْمُهَا رَغَدُ، وَهُوَ مُدَوَّنٌ عِنْدَكَ فِي صَكِّ مِلْكِيَّتِهَا", "segs": null, "full_uz": "Rag'ad, ismi Rag'ad, bu senda uning egalik hujjatida yozib qo'yilgan.", "note": "صَكُّ الْمِلْكِيَّة — mulk yoxud egalik hujjati."},
  {"num": 158, "time": "00:12:10,500 --> 00:12:15,920", "arabic": "لَكِنَّهَا فِي لَحَظَاتِ جُنُونِهَا الْقَلِيلَةِ تَعْتَقِدُ أَنَّ اسْمَهَا فَوْزٌ", "segs": null, "full_uz": "Lekin u kamdan-kam telbalik onlarida ismi Favz deb o'ylaydi.", "note": null},
  {"num": 159, "time": "00:12:15,919 --> 00:12:23,979", "arabic": "أَظُنُّ وَاللَّهُ أَعْلَمُ أَنَّهَا كَانَتْ تَعْرِفُ فَتَاةً بِهَذَا الِاسْمِ وَتَتَمَنَّى أَنْ تَكُونَ مَكَانَهَا فِي كُلِّ شَيْءٍ", "segs": null, "full_uz": "O'ylashimcha — Alloh yaxshiroq biladi — u shu ismli bir qizni tanigan va uning o'rnida bo'lishni orzu qilardi.", "note": null},
  {"num": 161, "time": "00:12:27,679 --> 00:12:28,740", "arabic": "لَا بَأْسَ", "segs": null, "full_uz": "Mayli, zarari yo'q.", "note": null},
  {"num": 162, "time": "00:12:28,740 --> 00:12:34,299", "arabic": "أَشْكُرُكَ لِأَنَّكَ لَفَتَّ نَظَرِي إِلَى هَذَا الْأَمْرِ، فَهَكَذَا أَعْرِفُ كَيْفَ أُعَامِلُهَا", "segs": null, "full_uz": "Bu masalaga e'tiborimni tortganing uchun senga rahmat — shunday qilib uni qanday muomala qilishni bilib olaman.", "note": null},
  {"num": 164, "time": "00:12:34,299 --> 00:12:39,939", "arabic": "وَالْآنَ هَلْ أَسْتَطِيعُ أَنْ آخُذَهَا وَنَذْهَبَ؟", "segs": null, "full_uz": "Endi uni olib, ketishimiz mumkinmi?", "note": null},
  {"num": 165, "time": "00:12:39,939 --> 00:12:41,139", "arabic": "حَتْمًا، بِالتَّأْكِيدِ", "segs": null, "full_uz": "Albatta, aniq shunday.", "note": null},
  {"num": 166, "time": "00:12:41,139 --> 00:12:46,639", "arabic": "يَا حَنْظَلَةُ، قُلْ لِرَغَدَ أَنْ تُجَهِّزَ نَفْسَهَا لِكَيْ تَذْهَبَ مَعَ سَيِّدِهَا إِلَى بَيْتِهِ", "segs": null, "full_uz": "Ey Hanzala, Rag'adga ayt — sayyidi bilan uning uyiga borish uchun o'zini hozirlasin.", "note": null},
  {"num": 167, "time": "00:12:46,639 --> 00:13:13,240", "arabic": "هَيَّا يَا فَوْزُ، لَقَدْ حَانَ مَوْعِدُ رَحِيلِكِ", "segs": [{"ar": "هَيَّا يَا فَوْزُ", "uz": "Yur, ey Favz"}, {"ar": "لَقَدْ حَانَ مَوْعِدُ رَحِيلِكِ", "uz": "ketish vaqting keldi"}], "full_uz": "Yur, ey Favz, ketish vaqting keldi.", "note": null},
  {"num": 169, "time": "00:13:13,240 --> 00:13:19,120", "arabic": "لَوْ تَعْلَمِينَ كَمْ أَنَا حَزِينٌ لِفِرَاقِكِ يَا فَوْزُ", "segs": null, "full_uz": "Bilsang edi, sendan ayrilganimdan qanchalik g'amginman, ey Favz.", "note": null},
  {"num": 170, "time": "00:13:19,120 --> 00:13:24,240", "arabic": "حَزِينٌ كَسَعَادَتِي بِخَلَاصِكِ مِنْ هَذَا الْبَيْتِ وَزَوْجَتِي زُمُرُّدَةَ", "segs": null, "full_uz": "Bu uydan va xotinim Zumurradadan qutulganingdan xursand bo'lganimdek g'amginman.", "note": "Jumla qarama-qarshi tuyg'ular — g'am va xursandlik — ustiga qurilgan."},
  {"num": 171, "time": "00:13:24,240 --> 00:13:26,360", "arabic": "لَقَدْ أَحْبَبْتُكِ كَأُخْتِي لِي", "segs": null, "full_uz": "Men seni o'zimning singlim kabi sevganman.", "note": null},
  {"num": 172, "time": "00:13:26,360 --> 00:13:33,060", "arabic": "لَكِنَّ خَوْفِيَ الْجَبَانَ هُوَ مَا مَنَعَنِي مِنَ الْبَوْحِ وَلَجَمَ لِسَانِي كُلَّ هَذِهِ السِّنِينَ", "segs": null, "full_uz": "Lekin qo'rqoq qo'rquvim meni ochiq gapirishdan to'sib, shuncha yillar tilimni jilovlab keldi.", "note": null},
  {"num": 174, "time": "00:13:33,060 --> 00:13:37,779", "arabic": "كُلُّ مَا أَتَمَنَّاهُ أَنْ تُسَامِحِينِي عَلَى مَا فَعَلْنَاهُ بِكِ", "segs": null, "full_uz": "Faqat tilaganim — bizning senga qilgan ishimiz uchun meni kechirishing.", "note": null},
  {"num": 175, "time": "00:13:37,779 --> 00:13:39,100", "arabic": "لَا تُكْمِلْ", "segs": null, "full_uz": "Davom ettirma.", "note": null},
  {"num": 176, "time": "00:13:39,100 --> 00:13:43,700", "arabic": "كَانَتْ أَفْعَالُكَ تُخْبِرُنِي بِمَا تُكِنُّهُ لِي مِنْ شَفَقَةٍ وَحَنَانٍ", "segs": null, "full_uz": "Qilmishlaring menga ichingda saqlagan shafqat va mehringdan xabar berib turardi.", "note": "يُكِنُّ — dilida yashirib saqlamoq, ichiga bekitmoq."},
  {"num": 177, "time": "00:13:43,700 --> 00:13:47,080", "arabic": "لَنْ أَنْسَى مَا قَدَّمْتَهُ لِي أَبَدًا", "segs": null, "full_uz": "Menga qilgan yaxshiliklaringni hech qachon unutmayman.", "note": null},
  {"num": 178, "time": "00:13:47,080 --> 00:13:59,740", "arabic": "وَلَكِنْ إِنْ أَرَدْتَ نَصِيحَتِي، لَا تَجْعَلِ الْخَوْفَ يَغْتَالُ قَلْبَكَ الطَّيِّبَ، فَآفَةُ الرِّجَالِ الْخَوْفُ", "segs": null, "full_uz": "Ammo agar nasihatimni istasang — qo'rquvga yaxshi qalbingni o'ldirishga yo'l qo'yma, chunki erkaklarning ofati qo'rquvdir.", "note": "آفَةُ الرِّجَالِ الْخَوْف — hikmatona ibora: «erkaklarning balosi qo'rquvdir»."},
  {"num": 181, "time": "00:13:59,740 --> 00:14:04,000", "arabic": "هَيَّا يَا حَنْظَلَةُ، لَا نُرِيدُ أَنْ نُؤَخِّرَ السَّيِّدَةَ أَكْثَرَ مِنْ هَذَا", "segs": null, "full_uz": "Yur, Hanzala, xonimni bundan ortiq ushlab turmaylik.", "note": null},
  {"num": 183, "time": "00:14:04,000 --> 00:14:11,940", "arabic": "كُلُّ مَا أَتَمَنَّاهُ أَنْ يُعَوِّضَكِ اللَّهُ عَنْ بُؤْسِ أَيَّامِكِ مَعَنَا، حَمَاكِ اللَّهُ", "segs": null, "full_uz": "Faqat tilaganim — Alloh oramizda o'tgan achchiq kunlaring o'rniga senga ezgulik bersin. Alloh seni asrasin.", "note": null},
  {"num": 185, "time": "00:14:11,940 --> 00:14:14,360", "arabic": "هَيَّا بِنَا، هَيَّا", "segs": null, "full_uz": "Yuring, ketdik, yur.", "note": null},
  {"num": 187, "time": "00:14:14,360 --> 00:14:23,740", "arabic": "إِنَّ الْقُرْآنَ مَخْلُوقٌ، خَلَقَهُ اللَّهُ فِي نَفْسِ جِبْرِيلَ", "segs": null, "full_uz": "Qur'on yaratilgandir — Alloh uni Jabroilning zotida yaratdi.", "note": null},
  {"num": 189, "time": "00:14:23,740 --> 00:14:30,899", "arabic": "فَنَقَلَ جِبْرِيلُ مَا خُلِقَ فِي نَفْسِهِ فَأَلْقَاهُ إِلَى الرَّسُولِ", "segs": null, "full_uz": "Jabroil o'z zotida yaratilganini yetkazib, Rasulga topshirdi.", "note": null},
  {"num": 191, "time": "00:14:30,899 --> 00:14:37,899", "arabic": "فَكَانَ دَلَالَةً لَنَا عَلَى الْأَحْكَامِ لِنَرْجِعَ إِلَيْهِ فِي الْحَلَالِ وَالْحَرَامِ", "segs": null, "full_uz": "Shunday qilib u bizga halol va harom masalasida murojaat qilishimiz uchun hukmlarga dalolat bo'ldi.", "note": null},
  {"num": 192, "time": "00:14:38,579 --> 00:14:43,899", "arabic": "إِنَّ الْقُرْآنَ يُخْلَقُ فِي أَحْوَالٍ مُخْتَلِفَةٍ", "segs": null, "full_uz": "Qur'on turli holatlarda yaratiladi.", "note": null},
  {"num": 193, "time": "00:14:44,620 --> 00:14:52,899", "arabic": "مِنْ جِهَةِ تَكْلِيمِ مُوسَى خَلَقَ اللَّهُ الْكَلَامَ فِي الشَّجَرَةِ، أَيْنَ خَلَقَهُ؟", "segs": [{"ar": "مِنْ جِهَةِ تَكْلِيمِ مُوسَى خَلَقَ اللَّهُ الْكَلَامَ فِي الشَّجَرَةِ", "uz": "Muso bilan so'zlashish jihatidan, Alloh so'zni daraxtda yaratdi"}, {"ar": "أَيْنَ خَلَقَهُ؟", "uz": "qayerda yaratdi?"}], "full_uz": "Muso bilan so'zlashish jihatidan, Alloh so'zni daraxtda yaratdi — qayerda yaratdi?", "note": null},
  {"num": 195, "time": "00:14:52,899 --> 00:15:02,639", "arabic": "فِي الشَّجَرَةِ", "segs": null, "full_uz": "Daraxtda.", "note": null},
  {"num": 196, "time": "00:15:02,639 --> 00:15:08,939", "arabic": "أَتَخْرُجِينَ وَأَنْتِ لَمْ تَنْبِسِي بِبِنْتِ شَفَةٍ؟ فَلَمْ تَسْأَلِي نَفْسَكِ لِمَ عَطَسْتِ؟", "segs": null, "full_uz": "Bir og'iz so'z aytmay chiqib ketyapsanmi? Nega aksirganingni o'zingdan so'ramading-ku?", "note": "لَمْ يَنْبِسْ بِبِنْتِ شَفَة — arab tilidagi ibora, «bir og'iz ham so'z aytmadi» degan ma'noni bildiradi."},
  {"num": 198, "time": "00:15:08,939 --> 00:15:12,100", "arabic": "مُجَرَّدُ أَنَّكِ عَطَسْتِ فَهَذَا يَعْنِي أَنَّكِ وُفِّقْتِ", "segs": null, "full_uz": "Aksirganing — bu senga omad kulib boqqanini bildiradi.", "note": "Arab xalq e'tiqodida aksirish ko'pincha yaxshi alomat sifatida talqin qilingan."},
  {"num": 199, "time": "00:15:12,100 --> 00:15:18,799", "arabic": "لَنْ تَكُونِي فِي دَارِي إِلَّا عَزِيزَةً مُكَرَّمَةً، لَكِنْ إِنْ وُفِّقْتِ أَنْتِ عَلَى شَرْطِي", "segs": null, "full_uz": "Uyimda faqat aziz-mukarram bo'lasan — ammo bu mening shartimga muvofiq bo'lsang.", "note": null},
  {"num": 201, "time": "00:15:18,799 --> 00:15:23,740", "arabic": "مَا هُوَ شَرْطُكِ؟ أُخْتِي وَحِيدَتِي وَهِيَ مَنْ تَبَقَّى لِي مِنْ عَائِلَتِي", "segs": [{"ar": "مَا هُوَ شَرْطُكِ؟", "uz": "Shartingiz nima?"}, {"ar": "أُخْتِي وَحِيدَتِي وَهِيَ مَنْ تَبَقَّى لِي مِنْ عَائِلَتِي", "uz": "Yolg'iz singlim, oilamdan menga qolgan yagona kishi"}], "full_uz": "Shartingiz nima? — Yolg'iz singlim, oilamdan menga qolgan yagona kishi.", "note": null},
  {"num": 203, "time": "00:15:23,740 --> 00:15:31,620", "arabic": "أُرِيدُكِ أَنْ تَرْعَيْهَا وَتَهْتَمِّي بِكُلِّ مَا تَطْلُبُهُ مِنْكِ، وَتُعَوِّضِيهَا عَنْ حَالِهَا حُبًّا وَحَنَانًا وَحُسْنَ رِعَايَةٍ", "segs": null, "full_uz": "Undan g'amxo'rlik qilib, u nima talab qilsa e'tibor berishingni, ahvoliga muhabbat, mehr va yaxshi qarash bilan o'rin to'ldirishingni istayman.", "note": null},
  {"num": 205, "time": "00:15:31,620 --> 00:15:39,519", "arabic": "فَإِنْ كَانَتْ سَعِيدَةً فَسَتَرَيْنَ السَّعَادَةَ، وَإِنْ قَصَّرْتِ فِيمَا تَطْلُبُهُ مِنْكِ", "segs": [{"ar": "فَإِنْ كَانَتْ سَعِيدَةً فَسَتَرَيْنَ السَّعَادَةَ", "uz": "Agar u baxtli bo'lsa, baxtni ko'rasan"}, {"ar": "وَإِنْ قَصَّرْتِ فِيمَا تَطْلُبُهُ مِنْكِ", "uz": "agar undan so'raganida sustkashlik qilsang"}], "full_uz": "Agar u baxtli bo'lsa — baxtni ko'rasan, agar undan so'raganida sustkashlik qilsang esa...", "note": null},
  {"num": 207, "time": "00:15:39,519 --> 00:15:46,180", "arabic": "حِينَهَا لَا أَعْلَمُ مَاذَا يُمْكِنُ أَنْ أَفْعَلَ، أُعِيذُكِ أَنْ أَتَّخِذَ جُهْدًا لِأَجْلِهَا", "segs": null, "full_uz": "O'shanda nima qilishimni bilmayman — sen uchun harakat qilishimga zaruriyat qoldirma.", "note": "'أُعِيذُكِ' — bu yerda ogohlantirish ma'nosida, «Alloh saqlasin (shunday qilishdan)» kabi ishlatilgan."},
  {"num": 209, "time": "00:15:53,740 --> 00:16:07,299", "arabic": "تَاجِرٌ فِي بَغْدَادَ، كَانَ أَبِي يَبِيعُ لَهُ أَمْشَاطًا", "segs": null, "full_uz": "Bag'dodlik bir savdogar — otam unga taroqlar sotardi.", "note": null},
  {"num": 211, "time": "00:16:23,740 --> 00:16:36,779", "arabic": "أَلَمْ تَنَمْ بَعْدُ يَا فَرَّازُ؟ لَا يَا أُمِّي", "segs": [{"ar": "أَلَمْ تَنَمْ بَعْدُ يَا فَرَّازُ؟", "uz": "Hali uxlamadingmi, Farroz?"}, {"ar": "لَا يَا أُمِّي", "uz": "Yo'q, onajon"}], "full_uz": "Hali uxlamadingmi, Farroz? Yo'q, onajon.", "note": null},
  {"num": 213, "time": "00:16:36,779 --> 00:16:41,600", "arabic": "أَتُرِيدِينَ شَيْئًا؟ أَلَا يَكْفِيكِ الْعَمَلُ طِيلَةَ النَّهَارِ؟", "segs": null, "full_uz": "Biror narsa kerakmi? Kun bo'yi ishlaganing yetmadimi?", "note": null},
  {"num": 215, "time": "00:16:41,600 --> 00:16:46,519", "arabic": "لَا عَلَيْكِ، سَأَنْتَهِي بَعْدَ قَلِيلٍ. تُصْبِحِينَ عَلَى خَيْرٍ", "segs": null, "full_uz": "Xavotir olma, tez orada tugataman. Xayrli tun.", "note": null},
  {"num": 217, "time": "00:16:46,519 --> 00:16:50,639", "arabic": "كَانَ اللَّهُ فِي عَوْنِكَ يَا فَرَّازُ. تُصْبِحُ عَلَى خَيْرٍ", "segs": null, "full_uz": "Alloh senga yordamchi bo'lsin, Farroz. Xayrli tun.", "note": null},
  {"num": 219, "time": "00:16:50,639 --> 00:17:20,180", "arabic": "أَيُّ عَقْلٍ أَنْ أُعَرِّضَ نَفْسِي لِلتَّهْلُكَةِ، وَيَذْهَبَ أَبُو سَرْحَانَ وَحْدَهُ بِحُظْوَةٍ وَمَجْدٍ فِي بَلَاطِ أَمِيرِ الْمُؤْمِنِينَ", "segs": [{"ar": "أَيُّ عَقْلٍ أَنْ أُعَرِّضَ نَفْسِي لِلتَّهْلُكَةِ", "uz": "Qanday aql bilan o'zimni halokatga tashlayman"}, {"ar": "وَيَذْهَبَ أَبُو سَرْحَانَ وَحْدَهُ بِحُظْوَةٍ وَمَجْدٍ فِي بَلَاطِ أَمِيرِ الْمُؤْمِنِينَ", "uz": "Abu Sarhon esa yolg'iz Amir al-Mo'minin saroyida obro' va shon-shuhratga erishsin"}], "full_uz": "Qanday aqldan bo'ladi — o'zimni halokatga tashlab, Abu Sarhon esa yolg'iz Amir al-Mo'minin saroyida obro' va shon-shuhratga erishsa?", "note": null},
  {"num": 221, "time": "00:17:20,180 --> 00:17:25,980", "arabic": "هَذَا كَنْزٌ أَثْمَنُ مِنْ أَنْ تَضَعَهُ بَيْنَ يَدَيْ أَبِي سَرْحَانَةَ يَا فَرَشُ", "segs": null, "full_uz": "Bu xazina Abu Sarhonaga topshirishing uchun juda qimmatlidir, Farash.", "note": null},
  {"num": 222, "time": "00:17:25,980 --> 00:17:31,060", "arabic": "هَذَا الْكَنْزُ يَجِبُ أَنْ تُوصِلَهُ بِنَفْسِكَ إِلَى الْقَصْرِ", "segs": null, "full_uz": "Bu xazinani sen o'zing saroyga yetkazishing kerak.", "note": null},
  {"num": 223, "time": "00:17:31,060 --> 00:17:35,940", "arabic": "وَلَكِنْ كَيْفَ السَّبِيلُ إِلَى ذَلِكَ يَا فَرَشُ؟", "segs": null, "full_uz": "Ammo bunga qanday yo'l bor, Farash?", "note": null},
  {"num": 224, "time": "00:17:35,940 --> 00:17:44,600", "arabic": "مَا بِكَ يَا أَحْمَقُ؟ سَتَنْسَى مَا قَالَهُ الْمَرِيسِيُّ وَأَنْتَ سَادِرٌ فِي أَوْهَامِكَ وَأَحْلَامِكَ الزَّائِفَةِ", "segs": null, "full_uz": "Senga nima bo'ldi, ahmoq? Yolg'on xayollaring va tushlaring ichida g'aflatda qolib, al-Marisiy aytganini unutasan.", "note": null},
  {"num": 226, "time": "00:17:44,600 --> 00:17:47,360", "arabic": "أَنْهِ مَا حَفِظْتَهُ مِنْ مَقَالَةِ الْمُعْتَزِلَةِ", "segs": null, "full_uz": "Mo'tazila ta'limotidan yodlaganingni tugat.", "note": null},
  {"num": 227, "time": "00:17:47,359 --> 00:17:53,279", "arabic": "وَبَعْدَهَا أُفَكِّرُ كَمَا تَشَاءُ فِي كَيْفِيَّةِ إِيصَالِهِ إِلَى الْقَصْرِ", "segs": null, "full_uz": "Undan keyin uni saroyga qanday yetkazish haqida xohlaganingcha o'ylab ko'raman.", "note": null},
  {"num": 229, "time": "00:17:55,240 --> 00:18:07,240", "arabic": "هَا قَدْ جِئْتُكَ بِجَارِيَتِكَ رَغَدَ", "segs": null, "full_uz": "Mana, cho'ring Rag'adni senga olib keldim.", "note": null},
  {"num": 230, "time": "00:18:07,240 --> 00:18:12,399", "arabic": "أَتَمَنَّى عَلَى سَيِّدَتِي أَنْ تُنَادِيَنِي بِاسْمِ فَوْزَ وَلَيْسَ رَغَدَ", "segs": null, "full_uz": "Xonimimdan istagim — meni Rag'ad emas, Favz deb chaqirsin.", "note": null},
  {"num": 231, "time": "00:18:12,399 --> 00:18:17,099", "arabic": "وَلِمَ أُنَادِيكِ بِاسْمِ فَوْزَ إِنْ كَانَ اسْمُكِ رَغَدَ؟", "segs": null, "full_uz": "Ismingni Rag'ad bo'lsa, nega seni Favz deb chaqiraman?", "note": null},
  {"num": 232, "time": "00:18:17,099 --> 00:18:31,500", "arabic": "هَذِهِ قِصَّةٌ طَوِيلَةٌ سَأُخْبِرُكِ بِهَا فِيمَا بَعْدُ", "segs": null, "full_uz": "Bu uzun bir hikoya, senga keyinroq aytib beraman.", "note": null},
  {"num": 233, "time": "00:18:31,500 --> 00:18:36,659", "arabic": "وَهَلْ لِأَمْثَالِهَا مِنَ الْجَوَارِي قِصَصٌ تُرْوَى؟", "segs": null, "full_uz": "Uning kabi cho'rilarning aytiladigan hikoyasi bo'ladimi?", "note": null},
  {"num": 234, "time": "00:18:36,659 --> 00:18:44,199", "arabic": "قَدْ تَكُونُ لِي قِصَّةٌ طَوِيلَةٌ ظَالِمَةٌ، جَعَلَتْ مِنِّي جَارِيَةً بَعْدَ أَنْ كُنْتُ فَتَاةً حُرَّةً", "segs": null, "full_uz": "Balki mening uzun va adolatsiz hikoyam bordir — meni ozod qiz bo'lgan holimdan cho'riga aylantirgan.", "note": null},
  {"num": 236, "time": "00:18:44,199 --> 00:18:47,900", "arabic": "كُلُّهُنَّ يَزْعُمْنَ ذَلِكَ، الْمُهِمُّ أَنَّكِ الْآنَ عِنْدِي جَارِيَةٌ", "segs": null, "full_uz": "Barchalari shunday deyishadi — muhimi, endi sen mening cho'rimsan.", "note": null},
  {"num": 238, "time": "00:18:47,900 --> 00:19:01,200", "arabic": "وَأَنْتِ هُنَا فِي هَذَا الْبَيْتِ لِخِدْمَتِنَا فَحَسْبُ، أَمْ أَرَاكِ تَعْتَرِضِينَ عَلَى هَذَا أَيْضًا؟", "segs": null, "full_uz": "Sen bu uyda faqat bizga xizmat qilish uchunsan — yoki buni ham e'tiroz qilyapsanmi?", "note": null},
  {"num": 240, "time": "00:19:06,200 --> 00:19:12,160", "arabic": "أَلَمْ تَسْمَعْ أَنَّهُ جَاءَ إِلَى تَاجِرٍ آخَرَ فِي بَغْدَادَ؟ لَا، لَوْ أَنَّهُ أَتَى بَغْدَادَ الْعَرَجَ عَلَيْهِ", "segs": [{"ar": "أَلَمْ تَسْمَعْ أَنَّهُ جَاءَ إِلَى تَاجِرٍ آخَرَ فِي بَغْدَادَ؟", "uz": "Boshqa bir bag'dodlik savdogarga kelganini eshitmadingmi?"}, {"ar": "لَا، لَوْ أَنَّهُ أَتَى بَغْدَادَ الْعَرَجَ عَلَيْهِ", "uz": "Yo'q — Bag'dodga kelganida oyog'i cho'loq bo'lib qolsin"}], "full_uz": "Boshqa bir bag'dodlik savdogarga kelganini eshitmadingmi? Yo'q — Bag'dodga kelganida oyog'i cho'loq bo'lib qolsin.", "note": "اَلْعَرَجُ عَلَيْهِ — arab tilida qarg'ish/beddуо shakli, «unga falokat yetsin» ma'nosida."},
  {"num": 242, "time": "00:19:12,160 --> 00:19:16,300", "arabic": "جَزَاكَ اللَّهُ خَيْرًا. السَّلَامُ عَلَيْكُمْ. وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Alloh senga yaxshilik ato etsin. Assalomu alaykum. Va alaykum assalom.", "note": null},
  {"num": 245, "time": "00:19:16,300 --> 00:19:28,420", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 247, "time": "00:19:28,420 --> 00:19:35,820", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ. كَيْفَ حَالُ زِينَةِ شَبَابِ بَغْدَادَ وَدُرَرِهَا الْمُتَلَأْلِئَةِ؟", "segs": [{"ar": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "uz": "Va alaykum assalom va rahmatullah"}, {"ar": "كَيْفَ حَالُ زِينَةِ شَبَابِ بَغْدَادَ وَدُرَرِهَا الْمُتَلَأْلِئَةِ؟", "uz": "Bag'dod yoshlarining ziynati va uning yaltiroq durlari qandayin?"}], "full_uz": "Va alaykum assalom va rahmatullah. Bag'dod yoshlarining ziynati va uning yaltiroq durlari qandayin?", "note": null},
  {"num": 250, "time": "00:19:35,820 --> 00:19:40,880", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَبَا مَحْفُوظٍ. مِنْ أَيْنَ لَنَا أَنْ نَكُونَ كَمَا وَصَفْتَ؟", "segs": null, "full_uz": "Alloh senga barakot bersin, Abu Mahfuz. Sen tasvirlagandek bo'lish qayoqda bizga?", "note": null},
  {"num": 252, "time": "00:19:40,880 --> 00:19:48,620", "arabic": "وَهَلْ هُنَاكَ أَزْيَنُ مِنْ حَمَلَةِ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟", "segs": null, "full_uz": "Rasululloh sollallohu alayhi va sallamning hadisini olib yuruvchilardan ko'rkamroq kim bor?", "note": null},
  {"num": 254, "time": "00:19:48,620 --> 00:20:01,120", "arabic": "إِنَّنِي حِينَ تَقَعُ عَيْنِي عَلَى أَحَدِكُمْ فَكَأَنَّنِي رَأَيْتُ رَجُلًا مِنْ صَحَابَةِ الرَّسُولِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Ko'zim sizlardan biriga tushganida, xuddi Muhammad sollallohu alayhi va sallamning sahobalaridan birini ko'rgandek bo'laman.", "note": null},
  {"num": 257, "time": "00:20:03,360 --> 00:20:10,620", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَبَا مَحْفُوظٍ عَلَى حُسْنِ ظَنِّكَ فِينَا، وَلَكِنْ أَيْنَ نَحْنُ مِنْ هَؤُلَاءِ الْقَوْمِ؟", "segs": null, "full_uz": "Alloh senga barakot bersin, Abu Mahfuz, biz haqimizdagi yaxshi gumoning uchun — ammo biz bu qavmdan qayoqdamiz?", "note": null},
  {"num": 259, "time": "00:20:10,619 --> 00:20:19,899", "arabic": "إِنَّ أَحَدَنَا لَوِ اجْتَهَدَ دَهْرًا مَا بَلَغَ مُدَّةَ أَحَدِهِمْ وَلَا نِصْفَهَا، فَمَا بَالُكَ بِمَنْ نَظَرَ إِلَى وَجْهِ رَسُولِ اللَّهِ؟", "segs": [{"ar": "إِنَّ أَحَدَنَا لَوِ اجْتَهَدَ دَهْرًا مَا بَلَغَ مُدَّةَ أَحَدِهِمْ وَلَا نِصْفَهَا", "uz": "Birimiz umr bo'yi tirishsa ham, ularning birortasining martabasiga, hatto yarmiga ham yetolmaydi"}, {"ar": "فَمَا بَالُكَ بِمَنْ نَظَرَ إِلَى وَجْهِ رَسُولِ اللَّهِ؟", "uz": "Rasululloh yuziga nazar solgan kishi haqida nima deysan?"}], "full_uz": "Birimiz umr bo'yi tirishsa ham, ularning birortasining martabasiga, hatto yarmiga ham yetolmaydi — Rasululloh yuziga nazar solgan kishi haqida nima deysan?", "note": null},
  {"num": 261, "time": "00:20:19,899 --> 00:20:29,559", "arabic": "أَيَشْقَى بَعْدَهَا؟ اَللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى مَنْ صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ", "segs": null, "full_uz": "Undan keyin baxtsiz bo'larmidi? Allohumma, malaklar salovot aytgan zotga salovot va salom yo'lla.", "note": null},
  {"num": 265, "time": "00:20:29,559 --> 00:20:48,019", "arabic": "تَفَضَّلِي سَيِّدَتِي هَذَا طَعَامُكِ أَرْجُو أَنْ يَلَائِمَ رِضَاكِ، إِنْ أَرَدْتِ سَيِّدَتِي أَطْعَمْتُكِ بِيَدِي", "segs": [{"ar": "تَفَضَّلِي سَيِّدَتِي هَذَا طَعَامُكِ أَرْجُو أَنْ يَلَائِمَ رِضَاكِ", "uz": "Marhamat, xonim, mana taomingiz, rozi bo'lishingizni umid qilaman"}, {"ar": "إِنْ أَرَدْتِ سَيِّدَتِي أَطْعَمْتُكِ بِيَدِي", "uz": "Agar istasangiz, xonim, sizni o'z qo'lim bilan ovqatlantiraman"}], "full_uz": "Marhamat, xonim, mana taomingiz, rozi bo'lishingizni umid qilaman. Agar istasangiz, xonim, sizni o'z qo'lim bilan ovqatlantiraman.", "note": null},
  {"num": 267, "time": "00:20:48,019 --> 00:21:01,299", "arabic": "أَسْتَطِيعُ أَنْ آكُلَ وَحْدِي، لِمَاذَا تَقِفِينَ عِنْدَكِ يَا أَيَّتُهَا الْجَارِيَةُ؟", "segs": null, "full_uz": "O'zim yeya olaman — nega turibsan, cho'ri?", "note": null},
  {"num": 269, "time": "00:21:01,299 --> 00:21:07,979", "arabic": "إِنَّ أَعْمَالَ الدَّارِ لَا تَنْتَهِي، هَيَّا انْصَرِفِي إِلَى أَعْمَالِكِ", "segs": null, "full_uz": "Uy ishlari tugamaydi — bor, ishlaringga qayt.", "note": null},
  {"num": 271, "time": "00:21:07,980 --> 00:21:13,660", "arabic": "كَمَا تَشَاءِينَ سَيِّدَتِي، إِنِ احْتَجْتِ شَيْئًا نَادِينِي", "segs": null, "full_uz": "Xohlaganingizcha, xonim. Biror narsa kerak bo'lsa, meni chaqiring.", "note": null},
  {"num": 273, "time": "00:21:13,660 --> 00:21:14,720", "arabic": "أَكُونُ", "segs": null, "full_uz": "Bo'laman/Xo'p bo'ladi.", "note": null},
  {"num": 275, "time": "00:21:34,720 --> 00:21:47,279", "arabic": "وَلِلْمُعْتَزِلَةِ شَنَاعَاتٌ فِي إِنْكَارِهِمُ الْحَدِيثَ وَعَدَمِ الْتِفَاتِهِمْ إِلَيْهِ، فَقَدْ بَنَوْا مَذْهَبَهُمْ فِي إِنْكَارِ السُّنَّةِ عَلَى أَمْرَيْنِ", "segs": null, "full_uz": "Mo'tazilaning hadisni inkor etib, unga e'tibor bermasligida qabih ishlari bor — ular sunnatni inkor etish mazhabini ikki asosga qurganlar.", "note": null},
  {"num": 277, "time": "00:21:47,279 --> 00:21:57,199", "arabic": "اَلْأَوَّلُ التَّشْكِيكُ فِي عَدَالَةِ النَّقَلَةِ لَا سِيَّمَا الصَّحَابَةِ، وَالثَّانِي تَقْدِيمُ عُقُولِهِمْ عَلَى شَرْعِ اللَّهِ", "segs": [{"ar": "اَلْأَوَّلُ التَّشْكِيكُ فِي عَدَالَةِ النَّقَلَةِ لَا سِيَّمَا الصَّحَابَةِ", "uz": "Birinchisi — rivoyat qiluvchilarning, ayniqsa sahobalarning adolatiga shubha qilish"}, {"ar": "وَالثَّانِي تَقْدِيمُ عُقُولِهِمْ عَلَى شَرْعِ اللَّهِ", "uz": "ikkinchisi — o'z aqllarini Alloh shariatidan ustun qo'yish"}], "full_uz": "Birinchisi — rivoyat qiluvchilarning, ayniqsa sahobalarning adolatiga shubha qilish; ikkinchisi — o'z aqllarini Alloh shariatidan ustun qo'yish.", "note": null},
  {"num": 279, "time": "00:21:57,199 --> 00:22:06,399", "arabic": "لَقَدْ وَصَلَ الْغُلُوُّ بِعُمَرَ بْنِ عُبَيْدٍ الْمُعْتَزِلِيِّ، وَقَدْ ذَكَرُوا لَهُ حَدِيثًا عَنْ رَسُولِ اللَّهِ أَنَّهُ قَالَ", "segs": null, "full_uz": "Mo'tazila boshlig'i Umar ibn Ubayd haddan oshib ketgan darajaga yetdi — unga Rasululloh haqida bir hadis zikr qilishganida u shunday degan edi.", "note": null},
  {"num": 281, "time": "00:22:06,400 --> 00:22:16,180", "arabic": "لَوْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ هَذَا الْحَدِيثَ لَرَدَدْتُهُ، نَعُوذُ بِاللَّهِ مِنْ هَذَا الضَّلَالِ", "segs": null, "full_uz": "«Agar Rasululloh sollallohu alayhi va sallamning o'zi bu hadisni aytganini eshitsam ham, uni rad etardim» — bu adashuvdan Allohga sig'inamiz.", "note": null},
  {"num": 283, "time": "00:22:16,180 --> 00:22:24,980", "arabic": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى أَرِيكَتِهِ", "segs": null, "full_uz": "Rasululloh sollallohu alayhi va sallam aytdilar: «Sizlardan birortangizni to'shagiga suyanib o'tirgan holda topmayin.»", "note": null},
  {"num": 285, "time": "00:22:24,980 --> 00:22:35,540", "arabic": "يَأْتِيهِ الْأَمْرُ مِنْ أَمْرِي مِمَّا أَمَرْتُ بِهِ أَوْ نَهَيْتُ عَنْهُ، فَيَقُولُ: لَا أَدْرِي، مَا وَجَدْنَا فِي كِتَابِ اللَّهِ اتَّبَعْنَاهُ", "segs": null, "full_uz": "Menga tegishli buyruq — buyurgan yoki qaytargan narsam — unga yetadi-yu, u: «Bilmayman, Alloh kitobida topganimizga ergashamiz», deydi.", "note": null},
  {"num": 287, "time": "00:22:35,539 --> 00:22:43,039", "arabic": "سُبْحَانَ اللَّهِ، أَدْرَكْنَا هَذَا الزَّمَانَ الَّذِي يُنْكِرُ فِيهِ الْبَعْضُ حُجِّيَّةَ السُّنَّةِ", "segs": null, "full_uz": "Subhanalloh, ba'zilar sunnatning hujjat ekanligini inkor etadigan bunday zamonga yetib keldik.", "note": null},
  {"num": 288, "time": "00:22:43,039 --> 00:22:52,500", "arabic": "لَا رَيْبَ أَنَّ الِاعْتِصَامَ بِكِتَابِ اللَّهِ وَالسُّنَّةِ هُوَ مِنْ أَعْظَمِ مَا مَنَّ اللَّهُ بِهِ عَلَى هَذِهِ الْأُمَّةِ", "segs": null, "full_uz": "Shubhasiz, Alloh kitobi va sunnatiga mahkam yopishish — Allohning bu ummatga bergan eng buyuk ne'matlaridan biridir.", "note": null},
  {"num": 289, "time": "00:22:52,500 --> 00:23:03,539", "arabic": "لَمْ أَعْثُرْ عَلَى ذَلِكَ الرَّجُلِ إِلَّا بَعْدَ أَنْ طُفْتُ نِصْفَ أَسْوَاقِ بَغْدَادَ، وَمَاذَا قَالَ لَكِ؟", "segs": null, "full_uz": "U kishini Bag'dod bozorlarining yarmini aylanib chiqqanimdan keyingina topdim. Va u senga nima dedi?", "note": null},
  {"num": 291, "time": "00:23:03,539 --> 00:23:09,619", "arabic": "لَقَدْ تَذَكَّرَ أَبَاكِ حِينَ ذَكَرْتُ اسْمَهُ، أَحَقًّا مَا تَقُولُ؟ نَعَمْ", "segs": null, "full_uz": "Ismini eslatganimda otangni esladi. Rostdan ham shundaymi? Ha.", "note": null},
  {"num": 294, "time": "00:23:09,619 --> 00:23:17,619", "arabic": "وَيَبْدُو أَنَّ أَبَاكِ قَدْ عَادَ لِلْبَحْثِ عَنْكُمَا كَثِيرًا. عَنْكُمَا؟ أَجَلْ", "segs": null, "full_uz": "Otangiz sizlarni izlab ko'p marta qaytib kelganga o'xshaydi. Ikkovimizni deysizmi? Ha.", "note": null},
  {"num": 297, "time": "00:23:17,619 --> 00:23:25,659", "arabic": "يَبْدُو أَنَّ أُخْتَكِ فَوْزَ ضَاعَتْ أَيْضًا. مَاذَا؟ ضَاعَتْ أُخْتُهَا أَيْضًا؟ أَجَلْ يَا أُمِّي", "segs": null, "full_uz": "Singling Favz ham yo'qolganga o'xshaydi. Nima? Uning singlisi ham yo'qolganmi? Ha, onajon.", "note": null},
  {"num": 301, "time": "00:23:25,659 --> 00:23:33,859", "arabic": "فَحِينَ عَادَ وَالِدُ شَهْنَازَ إِلَى التَّاجِرِ كَانَ يَسْأَلُهُ عَنِ الْفَتَاتَيْنِ، وَقَالَ لَهُ التَّاجِرُ أَنَّ إِحْدَى الْفَتَاتَيْنِ قَدْ عَادَتْ وَسَأَلَتْ عَنْهُ", "segs": null, "full_uz": "Shahnozning otasi savdogarga qaytib kelganida ikki qiz haqida so'rar edi, savdogar esa unga ikki qizdan biri qaytib kelib uni so'raganini aytdi.", "note": null},
  {"num": 304, "time": "00:23:33,859 --> 00:23:39,119", "arabic": "إِنَّهَا فَوْزُ وَلَا شَكَّ، فَأَنَا لَمْ أَعُدْ إِلَى ذَلِكَ التَّاجِرِ أَبَدًا", "segs": null, "full_uz": "Bu, shubhasiz, Favz — men u savdogarga hech qachon qaytmagandim.", "note": null},
  {"num": 306, "time": "00:23:39,119 --> 00:23:47,799", "arabic": "وَأَخْبَرَنِي ذَلِكَ التَّاجِرُ أَنَّ أَبَاكِ عَادَ كَثِيرًا لِيَسْأَلَ عَنْكُمَا، وَلَكِنَّ أَخْبَارَهُمْ قُطِعَتْ مُنْذُ ثَلَاثِ سَنَوَاتٍ", "segs": null, "full_uz": "Savdogar menga otangiz sizlar haqida so'rab ko'p marta qaytib kelganini aytdi, ammo ularning xabari uch yildan beri kesilgan.", "note": null},
  {"num": 308, "time": "00:23:59,519 --> 00:24:07,059", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ، كَانَ اللَّهُ فِي عَوْنِي", "segs": null, "full_uz": "La havla va la quvvata — Alloh menga yordamchi bo'lsin.", "note": null},
  {"num": 310, "time": "00:24:07,059 --> 00:24:14,359", "arabic": "إِلَى السَّاعَةِ لَمْ تُخْبِرْنِي بِقَرَارِكَ يَا ابْنَ حَنْبَلٍ، هَلْ سَتُرَافِقُنِي إِلَى مَكَّةَ الْمُكَرَّمَةِ أَمْ لَا؟", "segs": null, "full_uz": "Hozirgacha qarorini menga aytmading, Ibn Hanbal — Makka Mukarramaga men bilan boradigan bo'lasanmi yo'qmi?", "note": null},
  {"num": 312, "time": "00:24:14,359 --> 00:24:20,960", "arabic": "مَا زِلْتُ فِي حَيْرَةٍ مِنْ أَمْرِي يَا ابْنَ مَعِينٍ، اَلدَّعْوَةُ إِلَى بَلَدِ اللَّهِ الْحَرَامِ فِي صُحْبَةِ أَنْتَ فِيهَا لَا تُرَدُّ", "segs": null, "full_uz": "Hali ham o'z ishimda taraddudda qolyapman, Ibn Ma'in — Allohning haram beldasiga taklif, sen unda hamroh bo'lsang, rad etilmaydi.", "note": null},
  {"num": 314, "time": "00:24:20,960 --> 00:24:26,460", "arabic": "وَلَكِنْ كَيْفَ سَأَتْرُكُ أُمِّي وَحْدَهَا؟ لَا أَظُنُّنِي أَسْتَطِيعُ ذَلِكَ", "segs": null, "full_uz": "Ammo onamni yolg'iz qoldirib qanday ketaman? Bunga qodir bo'lolmasam kerak.", "note": null},
  {"num": 316, "time": "00:24:26,460 --> 00:24:30,700", "arabic": "لَا تُبَالِغْ كَثِيرًا يَا ابْنَ حَنْبَلٍ، لَا تُبَالِغْ كَثِيرًا فِي هَذَا الْأَمْرِ", "segs": null, "full_uz": "Ortiqcha bo'rttirma, Ibn Hanbal, bu masalada haddan oshirma.", "note": null},
  {"num": 318, "time": "00:24:30,700 --> 00:24:44,020", "arabic": "كُلُّنَا يَعْلَمُ أَنَّ سَعَادَةَ أُمِّكَ أَنْ تَرَاكَ وَأَنْتَ تُكْمِلُ سَبِيلَ الْعِلْمِ الَّذِي بَدَأْتَهُ، وَأَنْ تُصْبِحَ شَيْخًا يُعَلِّمُ النَّاسَ الْعِلْمَ، لَا أَنْ تَجْلِسَ إِلَى جِوَارِهَا كَأَيِّ أُمٍّ وَأَيِّ طِفْلٍ", "segs": [{"ar": "كُلُّنَا يَعْلَمُ أَنَّ سَعَادَةَ أُمِّكَ أَنْ تَرَاكَ وَأَنْتَ تُكْمِلُ سَبِيلَ الْعِلْمِ الَّذِي بَدَأْتَهُ", "uz": "Hammamiz bilamiz — onangning baxti seni boshlagan ilm yo'lini davom ettirganingni ko'rishida"}, {"ar": "وَأَنْ تُصْبِحَ شَيْخًا يُعَلِّمُ النَّاسَ الْعِلْمَ", "uz": "va odamlarga ilm o'rgatuvchi shayx bo'lishingda"}, {"ar": "لَا أَنْ تَجْلِسَ إِلَى جِوَارِهَا كَأَيِّ أُمٍّ وَأَيِّ طِفْلٍ", "uz": "oddiy ona va bola kabi uning yonida o'tirishingda emas"}], "full_uz": "Hammamiz bilamiz — onangning baxti seni boshlagan ilm yo'lini davom ettirib, odamlarga ilm o'rgatuvchi shayx bo'lganingni ko'rishida, oddiy ona va bola kabi uning yonida o'tirishingda emas.", "note": null},
  {"num": 321, "time": "00:24:44,020 --> 00:24:53,780", "arabic": "أَكْرَمَكَ اللَّهُ، أَعْرِفُ ذَلِكَ جَيِّدًا، وَلَكِنْ لَيْسَ مِنَ الْبِرِّ أَنْ أُفَكِّرَ فِي نَفْسِي وَحَسْبُ، وَأَنَّ سُحْقَ أُمِّي عَلَيَّ وَإِنْ لَمْ تُجَاهِرْ بِهِ", "segs": null, "full_uz": "Alloh senga karam etsin, buni yaxshi bilaman, lekin faqat o'zim haqida o'ylashim ehson emas — onam og'ir ahvolda, ochiq aytmasa ham.", "note": null},
  {"num": 324, "time": "00:24:53,780 --> 00:25:04,180", "arabic": "كَمَا تَشَاءُ، فَكِّرْ فِيمَا قُلْتُ لَكَ وَسَأَنْتَظِرُ جَوَابَكَ. سَأَفْعَلُ إِنْ شَاءَ اللَّهُ، أَعِدُكَ بِذَلِكَ", "segs": null, "full_uz": "Xohlaganingcha, aytganimni o'yla — javobingni kutaman. Alloh xohlasa, shunday qilaman, senga va'da beraman.", "note": null},
  {"num": 327, "time": "00:25:04,180 --> 00:25:10,460", "arabic": "وَالْآنَ يَا ابْنَ حَنْبَلٍ، إِذَنْ لِي فَلَدَيَّ عَمَلٌ أُنْجِزُهُ، اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Endi, Ibn Hanbal, ijozat ber — bajarishim kerak bo'lgan ishim bor. Assalomu alaykum.", "note": null},
  {"num": 330, "time": "00:25:10,460 --> 00:25:12,059", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Va alaykum assalom va rahmatullah.", "note": null},
  {"num": 331, "time": "00:25:28,519 --> 00:25:35,779", "arabic": "لَقَدْ سَمِعْتُ مَا دَارَ بَيْنَكَ وَبَيْنَ يَحْيَى، أَنَا أَعْرِفُ أَنَّكَ تَفْعَلُ الْكَثِيرَ مِنْ أَجْلِي", "segs": null, "full_uz": "Sen bilan Yahyo o'rtasida gapirilganlarni eshitdim — men uchun ko'p narsa qilayotganingni bilaman.", "note": null},
  {"num": 333, "time": "00:25:35,779 --> 00:25:42,660", "arabic": "وَأَنَّكَ عُدْتَ مِنْ رِحْلَتِكَ إِلَى وَاسِطَ، أَنَّكَ لَا تُرِيدُ الِارْتِحَالَ إِلَى مَكَّةَ مِنْ أَجْلِي", "segs": null, "full_uz": "Voqadagi safaringdan qaytganingni, men uchun Makkaga safar qilishni istamayotganingni bilaman.", "note": null},
  {"num": 335, "time": "00:25:42,660 --> 00:25:52,900", "arabic": "وَلَكِنْ يَا وَلَدِي، سَعِدَتِ الْأُمُّ فِي أَنْ تَرَى وَلَدَهَا نَجْمًا سَاطِعًا يَتَلَأْلَأُ فِي دُنْيَا النَّاسِ", "segs": [{"ar": "وَلَكِنْ يَا وَلَدِي، سَعِدَتِ الْأُمُّ فِي أَنْ تَرَى وَلَدَهَا نَجْمًا سَاطِعًا", "uz": "Ammo o'g'lim, ona farzandini yorqin yulduz kabi ko'rishdan xursand bo'ladi"}, {"ar": "يَتَلَأْلَأُ فِي دُنْيَا النَّاسِ", "uz": "odamlar dunyosida charaqlab turgan"}], "full_uz": "Ammo o'g'lim, ona farzandini odamlar dunyosida charaqlab turgan yorqin yulduz kabi ko'rishdan xursand bo'ladi.", "note": null},
  {"num": 340, "time": "00:25:52,900 --> 00:25:57,839", "arabic": "لَا أَنْ تَرَاهُ إِلَى جِوَارِهَا خَافِتًا كَاسِفَ الْبَالِ", "segs": null, "full_uz": "Uni yonida so'nib, dili g'ash holda ko'rishdan emas.", "note": "كَاسِفُ الْبَال — ko'ngli xira, ruhi tushkun kishi haqida ishlatiladigan ibora."},
  {"num": 342, "time": "00:25:57,839 --> 00:26:09,879", "arabic": "ثُمَّ كَيْفَ لِي أَنْ أَقْبَلَ أَنْ تَبْقَى إِلَى جِوَارِي وَرِفَاقُكَ فِي الدَّرْبِ يَسْتَأْثِرُونَ دُونَكَ بِعُلَمَاءِ الْحِجَازِ وَغَيْرِهَا؟", "segs": [{"ar": "ثُمَّ كَيْفَ لِي أَنْ أَقْبَلَ أَنْ تَبْقَى إِلَى جِوَارِي", "uz": "Sen yonimda qolishingga qanday rozi bo'la olaman"}, {"ar": "وَرِفَاقُكَ فِي الدَّرْبِ يَسْتَأْثِرُونَ دُونَكَ بِعُلَمَاءِ الْحِجَازِ وَغَيْرِهَا؟", "uz": "yo'ldagi hamrohlaring esa Hijoz va boshqa yerlarning olimlaridan sendan mahrum holda bahramand bo'lsa?"}], "full_uz": "Yo'ldagi hamrohlaring Hijoz va boshqa yerlarning olimlaridan sendan mahrum holda bahramand bo'lib, sen esa yonimda qolishingga qanday rozi bo'la olaman?", "note": null},
  {"num": 344, "time": "00:26:09,879 --> 00:26:19,519", "arabic": "حَتَّى إِنْ كُنْتِ تَسْتَطِيعِينَ احْتِمَالَ فِرَاقِي يَا أُمَّهْ فَأَنَا مَنْ لَا يَسْتَطِيعُ ذَلِكَ، وَأَيُّ أُمٍّ تَسْتَطِيعُ احْتِمَالَ فِرَاقِ فِلَذَةِ كَبِدِهَا؟", "segs": null, "full_uz": "Sen mendan ayrilishga chidasang ham, ona, chidamaydigan — o'zimman, va qaysi ona jigarbandidan ayrilishga chidaydi?", "note": "فِلَذَةُ الْكَبِد — so'zma-so'z «jigar bo'lagi», ya'ni farzandga nisbatan ishlatiladigan mehr ifodasi."},
  {"num": 346, "time": "00:26:19,519 --> 00:26:27,559", "arabic": "أَعْلَمُ يَا بُنَيَّ أَنَّ كُلَّ لَحْظَةٍ تَمُرُّ فِي غِيَابِكَ أَحْسِبُهَا وَكَأَنَّهَا دَهْرًا بِأَكْمَلِهِ", "segs": null, "full_uz": "Bilaman, o'g'lim, sen yo'qligingda o'tgan har bir onni butun bir umr kabi his qilaman.", "note": null},
  {"num": 348, "time": "00:26:27,559 --> 00:26:42,599", "arabic": "وَلَكِنْ يَا بُنَيَّ عَلَيْكَ أَنْ تَنْسَى كُلَّ هَذَا وَأَنْ تَضَعَ نُصْبَ عَيْنَيْكَ مَا تُفَكِّرُ بِهِ فَقَطْ وَمَا تَصْبُو إِلَيْهِ", "segs": null, "full_uz": "Ammo o'g'lim, sen buning barchasini unutib, faqat nima haqida o'ylayotganing va nimaga intilayotganingni ko'z oldingga qo'yishing kerak.", "note": null},
  {"num": 351, "time": "00:26:42,599 --> 00:26:56,500", "arabic": "إِنْ كُنْتَ تُرِيدُ سَعَادَتِي، وَهَذَا مَعْنَاهُ أَنْ تُرَافِقَ ابْنَ مَعِينٍ فِي رِحْلَتِهِ، هَلْ فَهِمْتَ يَا وَلَدِي؟", "segs": null, "full_uz": "Agar mening baxtimni istasang, bu Ibn Ma'inga uning safarida hamroh bo'lishing degani — tushundingmi, o'g'lim?", "note": null},
  {"num": 354, "time": "00:26:57,559 --> 00:27:21,559", "arabic": "إِنَّ أَفْعَالَ الْخَلْقِ جَمِيعَهَا مِنْ حَرَكَاتٍ وَسُكُونٍ فِي الْأَقْوَالِ وَالْأَفْعَالِ لَيْسَتْ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ، لِمَاذَا؟", "segs": [{"ar": "إِنَّ أَفْعَالَ الْخَلْقِ جَمِيعَهَا مِنْ حَرَكَاتٍ وَسُكُونٍ فِي الْأَقْوَالِ وَالْأَفْعَالِ لَيْسَتْ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ", "uz": "Yaratilganlarning barcha qilmishlari — so'z va ishlaridagi harakat va sukunlar — Alloh azza va jallaning yaratganidan emas"}, {"ar": "لِمَاذَا؟", "uz": "Nega?"}], "full_uz": "Yaratilganlarning barcha qilmishlari — so'z va ishlaridagi harakat va sukunlar — Alloh azza va jallaning yaratganidan emas. Nega?", "note": null},
  {"num": 357, "time": "00:27:21,559 --> 00:27:32,100", "arabic": "لِأَنَّهُ لَا يَنْبَغِي لِلَّهِ إِلَّا فِعْلُ الْأَصْلَحِ لِعِبَادِهِ، وَكَثِيرٌ مِنْ أَفْعَالِ الْخَلْقِ لَيْسَتْ صَالِحَةً", "segs": null, "full_uz": "Chunki Allohga bandalari uchun faqat eng solih (yaxshi) ishni qilish loyiq — yaratilganlarning ko'p qilmishlari esa solih emas.", "note": null},
  {"num": 359, "time": "00:27:32,100 --> 00:27:41,640", "arabic": "هَا قَدْ أَصْبَحْتَ وَاحِدًا مِنْهُمْ وَتَعْرِفُ عَنْهُمْ كُلَّ شَيْءٍ، فَمَا الَّذِي تَنْتَظِرُهُ؟", "segs": null, "full_uz": "Mana, ulardan biriga aylanding va ular haqida hammasini bilasan — nimani kutyapsan?", "note": null},
  {"num": 361, "time": "00:27:41,640 --> 00:27:49,640", "arabic": "اَلْمَجْدُ يَنْتَظِرُكَ وَالتَّأَخُّرُ عَنِ انْتِهَازِهِ يُرْدِيكَ، قَدْ وَاتَتْكَ الْفُرْصَةُ فَاغْتَنِمْهَا", "segs": null, "full_uz": "Shon-shuhrat seni kutmoqda, undan foydalanishga kechikish esa seni halok qiladi — imkoniyat senga keldi, uni g'animat bil.", "note": null},
  {"num": 363, "time": "00:27:56,220 --> 00:28:06,279", "arabic": "مِسْكِينَةٌ يَا فَوْزُ، إِذَنْ فَقَطْ جَرَى لَكِ مَا جَرَى لِي، أَرْجُو أَنْ لَا يَكُونَ قَدْ أَصَابَكِ مَكْرُوهٌ", "segs": null, "full_uz": "Bechora Favz, demak senga ham xuddi menga bo'lgani sodir bo'lgan ekan — umid qilamanki, senga yomonlik yetmagandir.", "note": null},
  {"num": 366, "time": "00:28:06,279 --> 00:28:22,160", "arabic": "تُرَى هَلِ اهْتَدَيْتِ إِلَى أَبِيكِ أَمْ أَنَّكِ مِثْلِي", "segs": null, "full_uz": "Qiziq, otangni topib olдingmi, yoki men kabimisan?", "note": null},
  {"num": 368, "time": "00:28:22,160 --> 00:28:29,879", "arabic": "تَتَلَقَّفُكِ الطُّرُقَاتُ وَالْبُيُوتُ وَلَا أَدْرِي كَيْفَ هُوَ مَصِيرُكِ الْآنَ يَا أُخْتَهْ", "segs": null, "full_uz": "Ko'chalar va uylar seni bir-biriga uzatib yuborayotgandir — hozir taqdiring qanday ekanini bilmayman, singlim.", "note": null},
  {"num": 378, "time": "00:32:55,579 --> 00:33:02,579", "arabic": "اِسْمَعْنَا مَا عِنْدَكَ، بِأَمْرِ مَوْلَايَ", "segs": null, "full_uz": "Bizga nima borligini eshittir. Xo'jayinim buyrug'i bilan.", "note": null},
  {"num": 380, "time": "00:33:08,579 --> 00:33:11,579", "arabic": "مَا الْعَمَلُ؟ إِنَّهَا لَا تَكْفِي", "segs": null, "full_uz": "Nima qilamiz? Bu yetarli emas.", "note": null},
  {"num": 382, "time": "00:33:16,579 --> 00:33:23,579", "arabic": "مَا هَذَا؟ مِئَةُ دِرْهَمٍ، وَأَظُنُّ أَنَّهَا إِلَى مَا مَعَكَ مِنْ نُقُودٍ تَكْفِي", "segs": null, "full_uz": "Bu nima? Yuz dirham — o'ylashimcha, sendagi pulga qo'shilsa yetarli bo'ladi.", "note": null},
  {"num": 385, "time": "00:33:25,579 --> 00:33:36,359", "arabic": "مَا بِكَ لَا تَتَكَلَّمُ؟ هَلْ تَكْفِي أَمْ لَا؟ لَنْ آخُذَهَا يَا أُمِّي", "segs": null, "full_uz": "Senga nima bo'ldi, gapirmayapsan? Yetarlimi yo'qmi? Buni olmayman, onajon.", "note": null},
  {"num": 388, "time": "00:33:36,359 --> 00:33:42,179", "arabic": "فَهَذِهِ نَفَقَتُكَ، نَفَقَتِي؟ هُوَ مَا نَفَقَتِي أَيُّهَا الْفَتَى الشَّيْخُ", "segs": null, "full_uz": "Bu — sening xarajating-ku. Xarajatimmi? Xarajatim shu ekan-da, ey qariya yigit.", "note": "نَفَقَة — biror kishining kundalik ehtiyoji uchun beriladigan mablag', xarajat."},
  {"num": 391, "time": "00:33:42,179 --> 00:33:52,079", "arabic": "اَلْعَجُوزُ تَكْفِيهَا التَّمْرَةُ أَوِ التَّمْرَتَانِ، وَأَسْكُنُ فِي دَارِ أَبِيكَ، وَلِي الْأُجْرَةُ مِنْ دُكَّانِ أَبِيكَ، فَمَا حَاجَتِي بِمِئَةِ دِرْهَمٍ؟", "segs": null, "full_uz": "Bir qariyaga bir-ikkita xurmo yetarli, otangning uyida yashayman, otangning do'konidan ijara haqim bor — menga yuz dirham nima keragi bor?", "note": null},
  {"num": 395, "time": "00:33:52,740 --> 00:33:59,500", "arabic": "وَلَكِنْ يَا أُمِّي، لَا تَسْتَدْرِكْ دَائِمًا عَلَى كَلَامِي، هَلْ تُرِيدُ الْخُرُوجَ إِلَى مَكَّةَ الْمُكَرَّمَةِ أَمْ لَا؟", "segs": null, "full_uz": "Ammo, onajon... — Doim so'zimga e'tiroz bildiraverma — Makka Mukarramaga chiqishni istaysanmi, yo'qmi?", "note": null},
  {"num": 398, "time": "00:33:59,500 --> 00:34:05,840", "arabic": "أَجَلْ غَيْرَ أَنَّ... إِذَنْ خُذْهَا دُونَ نِقَاشٍ، هَيَّا أَيُّهَا الْفَتَى", "segs": null, "full_uz": "Ha, ammo... — Unda tortishmasdan ol, yur bo'ldi endi, yigitcha.", "note": null},
  {"num": 401, "time": "00:34:05,840 --> 00:34:15,140", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، مَاذَا أَفْعَلُ بِهَذَا الْفَتَى الْعَنِيدِ؟", "segs": null, "full_uz": "La havla va la quvvata illa billah — bu qaysar yigit bilan nima qilay?", "note": null},
  {"num": 403, "time": "00:34:15,140 --> 00:34:15,640", "arabic": "خُذْ", "segs": null, "full_uz": "Ol.", "note": null},
  {"num": 404, "time": "00:34:15,639 --> 00:34:29,879", "arabic": "أَخْبَارُكُمْ مَوْثُوقَةٌ يَا أَبَا الْعَبَّاسِ، اِبْنُ الرَّبِيعِ لَا يَرْفَعُ إِلَى مَوْلَاهُ الرَّشِيدِ إِلَّا بَعْدَ تَمْحِيصٍ وَتَبَيُّنٍ", "segs": null, "full_uz": "Xabarlaringiz ishonchli, Abu al-Abbos — Ibn ar-Rabi' xo'jayini ar-Rashidga faqat tekshirib, aniqlashtirgandan keyingina yetkazadi.", "note": "STT: \"مبثوقة\" — \"موثوقة\" (ishonchli) so'ziga tuzatildi."},
  {"num": 406, "time": "00:34:29,879 --> 00:34:43,019", "arabic": "وَقَدْ تَأَكَّدْنَا مِنْ صِحَّتِهَا بِطُرُقٍ شَتَّى وَبِعُيُونٍ رَاصِدَةٍ لَا تُخْطِئُ، وَقَدِ انْتَهَيْنَا إِلَى أَنَّ بَيْتَ الْعَنْكَبُوتِ يَنْسِجُهُ بِشْرٌ الْمَرِيسِيُّ", "segs": [{"ar": "وَقَدْ تَأَكَّدْنَا مِنْ صِحَّتِهَا بِطُرُقٍ شَتَّى وَبِعُيُونٍ رَاصِدَةٍ لَا تُخْطِئُ", "uz": "Uning to'g'riligiga har xil yo'llar va xato qilmaydigan ko'zlar orqali ishonch hosil qildik"}, {"ar": "وَقَدِ انْتَهَيْنَا إِلَى أَنَّ بَيْتَ الْعَنْكَبُوتِ يَنْسِجُهُ بِشْرٌ الْمَرِيسِيُّ", "uz": "o'rgimchak uyasini Bishr al-Marisiy to'quyotganiga xulosa qildik"}], "full_uz": "Uning to'g'riligiga har xil yo'llar va xato qilmaydigan ko'zlar orqali ishonch hosil qildik — o'rgimchak uyasini Bishr al-Marisiy to'quyotganiga xulosa qildik.", "note": null},
  {"num": 408, "time": "00:34:43,019 --> 00:34:53,239", "arabic": "وَثُمَامَةُ بْنُ الْأَشْرَسِ وَغَيْرُهُمَا مِمَّنْ وَرَدَتْ أَسْمَاؤُهُمْ فِي الرِّقَاعِ، وَهُمْ يَقُومُونَ بِنَشْرِ تَعَالِيمِهِمْ", "segs": null, "full_uz": "Va Sumoma ibn al-Ashras hamda varaqlarda ismlari kelgan boshqalar — ular o'z ta'limotlarini tarqatmoqdalar.", "note": null},
  {"num": 411, "time": "00:34:53,239 --> 00:35:01,619", "arabic": "وَآرَائِهِمْ بَيْنَ الْفِتْيَةِ وَالْيَافِعِينَ، وَلَا سِيَّمَا طُلَّابَ الْفِقْهِ وَالْحَدِيثِ", "segs": null, "full_uz": "Va o'z fikrlarini yoshlar va o'smirlar orasida, ayniqsa fiqh va hadis talabalari orasida tarqatishmoqda.", "note": null},
  {"num": 413, "time": "00:35:01,619 --> 00:35:09,139", "arabic": "أَعْدَاءُ اللَّهِ يَنْشُرُونَ الْبِدَعَ وَالضَّلَالَ، كَمْ مِنَ الْمَكَائِدِ تَحَاكُ لِهَذَا الدِّينِ وَأَهْلِهِ يَا ابْنَ الرَّبِيعِ؟", "segs": null, "full_uz": "Alloh dushmanlari bid'at va zalolatni tarqatmoqdalar — bu din va uning ahliga qancha fitna to'qilmoqda, Ibn ar-Rabi'?", "note": null},
  {"num": 416, "time": "00:35:09,139 --> 00:35:20,960", "arabic": "كَمْ؟ وَاللَّهِ، وَاللَّهِ لَأَقْطَعَنَّ دَابِرَ كُلِّ مَنْ أَفْسَدَ عَلَى النَّاسِ عَقِيدَتَهُمْ وَدِينَهُمْ، إِلَّا كَلَامَ اللَّهِ يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Qancha? Vallohi, vallohi — odamlarning aqidasi va dinini buzgan har bir kimsaning ildizini qirqib tashlayman, faqat Alloh kalomidan bo'lak, Ibn ar-Rabi'.", "note": null},
  {"num": 421, "time": "00:35:22,300 --> 00:35:28,519", "arabic": "لَقَدْ أَخَذْنَا أَمْرَنَا يَا مَوْلَايَ وَنَنْتَظِرُ أَمْرَ أَمِيرِ الْمُؤْمِنِينَ لِلْقَبْضِ عَلَيْهِمْ", "segs": null, "full_uz": "Buyrug'ingizni oldik, xo'jayinim, va ularni tutish uchun Amir al-Mo'minin farmonini kutmoqdamiz.", "note": null},
  {"num": 423, "time": "00:35:28,519 --> 00:35:37,480", "arabic": "أَعِدَّ لَهُمُ الْعُدَّةَ يَا ابْنَ الرَّبِيعِ، أَعِدَّ لَهُمُ الْعُدَّةَ وَلَا يُفْلِتَنَّ أَحَدٌ مِنْ قَبْضَتِكُمْ، اَلْمُعْتَزِلَةُ", "segs": null, "full_uz": "Ularga tayyorgarlik ko'r, Ibn ar-Rabi' — tayyorgarlik ko'r, sizning qo'lingizdan hech kim qochib qutulmasin. Mo'tazila!", "note": null},
  {"num": 426, "time": "00:35:37,480 --> 00:35:42,820", "arabic": "اَلْمُعْتَزِلَةُ يَا ابْنَ الرَّبِيعِ، هَيَّا، أَمْرٌ مَجْنُونٌ", "segs": null, "full_uz": "Mo'tazila, Ibn ar-Rabi'! Yur! Tentak buyruq.", "note": null},
  {"num": 429, "time": "00:35:42,820 --> 00:35:57,860", "arabic": "هَؤُلَاءِ الْمُخَذِّلُونَ تَرَكُوا الْبَيِّنَ الْمُحْكَمَ وَأَخَذُوا الْمُتَشَابِهَ وَالْمُخْتَلِفَ فِيهِ", "segs": null, "full_uz": "Bu xayerlashtiruvchilar aniq-muhkam oyatlarni tashlab, mutashobih va ixtilofli narsalarni oldilar.", "note": null},
  {"num": 431, "time": "00:36:03,860 --> 00:36:05,519", "arabic": "وَاللَّهِ مَا أَضَلَّ النَّاسَ إِلَّا الْهَوَى بِغَيْرِ عِلْمٍ", "segs": null, "full_uz": "Vallohi, odamlarni ilmsiz nafs-хaviyodan boshqa hech narsa adashtirmadi.", "note": null},
  {"num": 434, "time": "00:36:16,860 --> 00:36:30,420", "arabic": "يَا بَنْدَرُ، اُدْخُلْ", "segs": null, "full_uz": "Ey Bandar, kir.", "note": null},
  {"num": 435, "time": "00:36:40,860 --> 00:36:44,860", "arabic": "يَا بِشْرُ، يَا بَشِيرُ، لِمَ كُلُّ هَذَا الرُّعْبِ؟", "segs": null, "full_uz": "Ey Bishr, ey Bashir — bu qo'rquv nimasi?", "note": "Ushbu qatorda tovush yozuvi noaniq bo'lib, ehtimol qochayotgan Bishr al-Marisiyga qarata aytilgan bo'lishi mumkin."},
  {"num": 436, "time": "00:36:45,860 --> 00:36:51,860", "arabic": "زَبَانِيَةُ هَارُونَ الرَّشِيدِ فِي أَعْقَابِنَا، اَلنَّجَاةَ النَّجَاةَ يَا شَيْخُ", "segs": null, "full_uz": "Horun ar-Rashidning jallodlari ortimizda — qochish, qochish, shayx!", "note": null},
  {"num": 439, "time": "00:38:10,860 --> 00:38:14,860", "arabic": "هَيَّا، هَيَّا", "segs": null, "full_uz": "Yur, tezroq.", "note": null},
  {"num": 441, "time": "00:38:20,860 --> 00:38:24,860", "arabic": "هَيَّا بِسُرْعَةٍ، هَيَّا", "segs": null, "full_uz": "Tez bo'l, yur.", "note": "STT: \"بصرا\" — \"بسرعة\" (tezlik bilan) so'ziga tuzatildi."},
  {"num": 443, "time": "00:38:40,860 --> 00:38:55,420", "arabic": "أَيُعْقَلُ أَنْ تَكُونَ هَذِهِ نِهَايَتَكَ يَا ابْنَ الْأَشْرَسِ؟ أَيُعْقَلُ؟", "segs": null, "full_uz": "Bu sening oxiring bo'lishi mumkinmi, Ibn al-Ashras? Mumkinmi?", "note": null},
  {"num": 445, "time": "00:39:05,820 --> 00:39:11,639", "arabic": "كَيْفَ اسْتَطَاعَ الْمَرِيسِيُّ أَنْ يَهْرُبَ مِنْكُمْ؟ لَا أَدْرِي يَا مَوْلَايَ، لَا أَدْرِي", "segs": null, "full_uz": "Al-Marisiy sizlardan qanday qochib qutuldi? Bilmayman, xo'jayinim, bilmayman.", "note": null},
  {"num": 447, "time": "00:39:11,639 --> 00:39:22,639", "arabic": "رُبَّمَا وَصَلَ إِلَيْهِ الْخَبَرُ قَبْلَ أَنْ نَصِلَ، لَعَلَّ بَيْنَكُمْ عُيُونًا لِهَؤُلَاءِ الْمُفْسِدِينَ؟", "segs": null, "full_uz": "Balki biz yetib borishimizdan oldin unga xabar yetgandir. Sizlar orasida bu buzg'unchilarning josuslari bordir?", "note": null},
  {"num": 449, "time": "00:39:22,639 --> 00:39:27,480", "arabic": "لَيْسَ بَيْنَ جُنْدِنَا إِلَّا مَنْ يُخْلِصُ الْوَلَاءَ لِأَمِيرِ الْمُؤْمِنِينَ، كُنْ عَلَى ثِقَةٍ مِنْ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Qo'shinimiz ichida Amir al-Mo'mininga sodiq bo'lganlardan boshqasi yo'q — bunga ishonch hosil qiling, xo'jayinim.", "note": null},
  {"num": 451, "time": "00:39:27,480 --> 00:39:34,679", "arabic": "إِذَنْ كَيْفَ اسْتَطَاعَ أَنْ يُفْلِتَ مِنْكُمْ؟ كَيْفَ؟ لَقَدْ فَرَّ قَبْلَ أَنْ يَصِلَ جُنْدُنَا إِلَيْهِ يَا مَوْلَايَ", "segs": null, "full_uz": "Unda sizlardan qanday qutulib qochdi? Qanday? Qo'shinimiz yetib borishidan oldin u qochib ketgan edi, xo'jayinim.", "note": null},
  {"num": 453, "time": "00:39:34,679 --> 00:39:43,060", "arabic": "فَبَيْتُهُ فِي أَطْرَافِ بَغْدَادَ، وَبَعْدَ أَنْ قَبَضْنَا عَلَى الْكَثِيرِ مِنْ رِجَالِهِ وَصَرَ إِلَيْهِ أَحَدُهُمْ لِيُبَلِّغَهُ بِالْهُرُوبِ", "segs": null, "full_uz": "Uning uyi Bag'dod chetida — odamlaridan ko'pini qo'lga olganimizdan so'ng, ulardan biri unga qochish haqida xabar yetkazgan.", "note": null},
  {"num": 456, "time": "00:39:43,060 --> 00:39:46,460", "arabic": "بَعْدَ أَنْ رَأَى مَا رَأَى، هَذَا تَفْسِيرٌ مُحْتَمَلٌ يَا مَوْلَايَ", "segs": null, "full_uz": "Ko'rganini ko'rgandan keyin. Bu ehtimoldagi bir izohdir, xo'jayinim.", "note": null},
  {"num": 458, "time": "00:39:46,460 --> 00:39:49,500", "arabic": "سَنَتَعَقَّبُ الْفَارِّينَ مِنْهُمْ فَلَا تَقْلَقْ", "segs": null, "full_uz": "Ulardan qochganlarni ta'qib qilamiz, xavotir olmang.", "note": null},
  {"num": 459, "time": "00:40:00,860 --> 00:40:07,199", "arabic": "لَيْتَهُمْ قَبَضُوا عَلَى ذَلِكَ الثَّعْلَبِ الْمَاكِرِ ابْنِ أَبِي دُؤَادٍ، فَقَدْ سَمِعْتُ أَنَّ أَحَدًا لَمْ يَقْتَرِبْ مِنْهُ", "segs": null, "full_uz": "Koshki o'sha ayyor tulki Ibn Abi Duvodni ham tutgan bo'lishsa — eshitishimcha, hech kim unga yaqinlasholmagan.", "note": null},
  {"num": 461, "time": "00:40:07,199 --> 00:40:15,139", "arabic": "اِبْنُ أَبِي دُؤَادٍ وَأَمْثَالُهُ لَيْسُوا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ، كَيْفَ؟ أَلَيْسُوا جَمِيعًا مُبْتَدِعَةً وَمَنْهَجُهُمْ وَاحِدٌ؟", "segs": null, "full_uz": "Ibn Abi Duvod va uning kabilari al-Marisiy va uning jamoati kabi emas. Qanday qilib? Ularning barchasi bid'atchi emasmi va yo'nalishlari bir emasmi?", "note": null},
  {"num": 463, "time": "00:40:16,739 --> 00:40:22,339", "arabic": "لَيْسَ كُلُّ مَنْ وَقَعَ فِي بِدْعَةٍ يَصِيرُ مُبْتَدِعًا، وَلَيْسَ مَنْ جَاهَرَ بِالْبِدْعَةِ كَمَنْ كَتَمَهَا", "segs": null, "full_uz": "Bid'atga tushgan har kim bid'atchi bo'lib qolmaydi, va bid'atini oshkor qilgan kishi uni yashirgan kishi kabi emas.", "note": null},
  {"num": 465, "time": "00:40:22,339 --> 00:40:32,239", "arabic": "اِبْنُ أَبِي دُؤَادٍ وَآخَرُونَ مِنَ الْمُعْتَزِلَةِ يَكْتُمُونَ عَقَائِدَهُمْ، لَا كَالْمَرِيسِيِّ وَجَمَاعَتِهِ يُجَاهِرُونَ بِهَا بَلْ وَيَعْمَلُونَ عَلَى بَثِّهَا بَيْنَ النَّاسِ", "segs": null, "full_uz": "Ibn Abi Duvod va boshqa mo'taziliylar o'z aqidalarini yashirishadi — al-Marisiy va uning jamoati kabi ochiq aytib, odamlar orasida tarqatishga harakat qilishmaydi.", "note": null},
  {"num": 468, "time": "00:40:32,239 --> 00:40:40,179", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي أَرَاحَنَا مِنْهُمْ جَمِيعًا، أَمَّا أَنَا يَا أَبَا زَكَرِيَّا فَأَرْجُو لِأَمْثَالِهِمُ الْهِدَايَةَ", "segs": null, "full_uz": "Bizni ulardan qutqargan Allohga hamdlar bo'lsin. Men esa, Abu Zakariyo, ularga hidoyat tilayman.", "note": null},
  {"num": 470, "time": "00:40:40,179 --> 00:40:46,239", "arabic": "إِنْ عَادَ هَؤُلَاءِ إِلَى رَجُلِهِمْ نَالَنَا خَيْرُهُمْ، فَادْعُوا لَهُمْ بِالْهِدَايَةِ يَا ابْنَ مَعِينٍ", "segs": null, "full_uz": "Agar bular o'z insofiga qaytsa, ularning yaxshiligidan biz ham naf ko'ramiz — ularga hidoyat tila, Ibn Ma'in.", "note": null},
  {"num": 472, "time": "00:40:46,239 --> 00:40:54,239", "arabic": "دَعُونَا الْآنَ مِنْ سِيرَةِ هَؤُلَاءِ الْمُبْتَدِعَةِ، وَأَخْبِرُونَا مَتَى نَوَيْتُمُ الْخُرُوجَ إِلَى مُهِمَّةِ الْعِلْمِ وَالْوَحْيِ؟", "segs": null, "full_uz": "Bu bid'atchilar haqidagi gapni endi qo'yaylik — bizga ilm va vahiy vazifasiga qachon chiqishni niyat qilganingizni ayting.", "note": "STT: \"نهضة\" o'rniga \"مهمة\" ma'nosi mantiqan mos keladi."},
  {"num": 474, "time": "00:40:54,939 --> 00:41:04,480", "arabic": "ثَمَّةَ قَافِلَةٌ سَتَخْرُجُ إِلَى الْحَجِّ بَعْدَ غَدٍ، إِنْ رَأَيْتُمْ أَنْ نَخْرُجَ مَعَهُمْ، مَا رَأْيُكَ يَا أَبَا عَبْدِ اللَّهِ؟ عَلَى بَرَكَةِ اللَّهِ", "segs": null, "full_uz": "Indinga hajga chiqadigan bir karvon bor — ular bilan chiqishimizni ma'qul ko'rsangiz. Fikringiz qanday, Abu Abdulloh? Alloh barakasi bilan.", "note": null},
  {"num": 478, "time": "00:41:04,480 --> 00:41:16,059", "arabic": "تَعِسَ لَنَا نَلْتَهِي بِسَفَاسِفِ الْخَبَرِ وَغَيْرُنَا فَازَ بِحِصَّةِ الْأَسَدِ", "segs": null, "full_uz": "Biz mayda-chuyda xabarlar bilan ovora bo'lib, boshqalar shernikidek ulushni olganidan holimizga voy.", "note": "STT: \"تعسى\" — \"تعس\" (holiga voy!) so'ziga yaqinroq mantiqiy o'qish."},
  {"num": 480, "time": "00:41:16,059 --> 00:41:29,199", "arabic": "تَقْصِدُ الْمُعْتَزِلَةَ؟ وَهَلْ ثَمَّ خَبَرٌ الْيَوْمَ فِي بَغْدَادَ سِوَاهُ؟", "segs": null, "full_uz": "Mo'tazilani nazarda tutyapsanmi? Bugun Bag'dodda undan boshqa xabar bormi?", "note": null},
  {"num": 482, "time": "00:41:29,199 --> 00:41:37,199", "arabic": "أَنَّ صَاحِبَ خَبَرِ الْمُعْتَزِلَةِ لَا بُدَّ أَنَّهُ سَيَنَالُ مِنَ الْمُكَافَآتِ مَا لَمْ يَحْلُمْ بِهِ، هَذِهِ أَخْبَارٌ", "segs": null, "full_uz": "Mo'tazila xabarining egasi tush ko'rmagan mukofotlarga albatta erishadi. Mana bu — xabar deganing.", "note": null},
  {"num": 485, "time": "00:41:37,199 --> 00:41:44,859", "arabic": "لَا أَخْبَارٌ كَأَنْتَ الَّتِي لَا قِيمَةَ لَهَا، وَمَاذَا أَفْعَلُ يَا مُعَلِّمِي؟ مَاذَا أَفْعَلُ؟", "segs": null, "full_uz": "Sendagidek qimmatsiz xabarlar emas. Nima qilay, ustozim? Nima qilay?", "note": null},
  {"num": 487, "time": "00:41:44,859 --> 00:41:52,199", "arabic": "اُخْتَرِعْ أَخْبَارًا مِنْ عِنْدِي؟ لَا، لَا تَخْتَرِعْ، لَوْ أَتْعَبْتَ نَفْسَكَ قَلِيلًا حَصَلْنَا عَلَى خَبَرِ الْمُعْتَزِلَةِ قَبْلَ غَيْرِنَا", "segs": null, "full_uz": "O'zimdan xabar to'qiymi? Yo'q, to'qima — biroz zahmat chekkaningda, Mo'tazila xabarini boshqalardan oldin olgan bo'lardik.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}